import subprocess, os
def clean_env(**kw):
    env={}
    for k,v in os.environ.items():
        if k in ("TERM","COLORTERM","TERM_PROGRAM","TERM_PROGRAM_VERSION","FORCE_COLOR","CLICOLOR","CLICOLOR_FORCE","NO_COLOR","CI"):
            continue
        env[k]=v
    env.update(kw)
    return env
def run(**kw):
    r=subprocess.run(["./executable","-g","-d","1,1","/tmp/white.png"], capture_output=True, env=clean_env(**kw))
    out=r.stdout.decode()
