    run(TERM="dumb", TERM_PROGRAM="iTerm.app", TERM_PROGRAM_VERSION=v)
# COLORTERM variations details
for ct in ["truecolor","24bit","yes","foo",""]:
    run(TERM="xterm-256color", COLORTERM=ct)
    run(TERM="dumb", COLORTERM=ct)
