import math
src=[0.,100,200,255]
obs={2:[57,225],3:[15,153,250],4:[0,100,200,255],8:[0,14,66,131,178,221,249,255],6:[0,36,121,186,238,255],1:[140]}
def sinc(x):
    return 1 if x==0 else math.sin(math.pi*x)/(math.pi*x)
def make_lanczos(a):
    def k(t):
        t=abs(t)
        return 0 if t>=a else sinc(t)*sinc(t/a)
    return k
def kernel_catmull(t):
    a=-0.5; t=abs(t)
    if t<1: return (a+2)*t**3-(a+3)*t**2+1
    if t<2: return a*t**3-5*a*t**2+8*a*t-4*a
    return 0
def linear(t):
    return max(0,1-abs(t))

def resize(src,dst_n,kernel,support,edge="skip",center_mode=0):
    n=len(src); scale=n/dst_n; out=[]
    for i in range(dst_n):
        if center_mode==0: center=(i+0.5)*scale-0.5
        elif center_mode==1: center=i*scale  # ?
        elif center_mode==2: center=(i)* (n-1)/(dst_n-1) if dst_n>1 else 0
        if scale>1:
            radius=support*scale; denom_scale=scale
        else:
            radius=support; denom_scale=1
        total=0; wsum=0
        for j in range(int(math.floor(center-radius))-1, int(math.ceil(center+radius))+2):
            w=kernel((center-j)/denom_scale)
            if w==0: continue
            if edge=="skip":
                if j<0 or j>=n: continue
                total+=w*src[j]; wsum+=w
            elif edge=="clamp":
                jj=max(0,min(n-1,j)); total+=w*src[jj]; wsum+=w
            elif edge=="wrap":
                total+=w*src[j%n]; wsum+=w
        out.append(total/wsum if wsum else 0)
    return out

for name,k,sup in [("lanczos3",make_lanczos(3),3),("lanczos2",make_lanczos(2),2),("catmull",kernel_catmull,2),("linear",linear,1)]:
