import json, math, glob
def sinc(x): return 1 if x==0 else math.sin(math.pi*x)/(math.pi*x)
def lancz(t,a=3):
    t=abs(t); return 0 if t>=a else sinc(t)*sinc(t/a)
def weights(src_n,dst_n):
    scale=src_n/dst_n; ws=[]
    for i in range(dst_n):
        center=(i+0.5)*scale-0.5
        if scale>1: radius=3*scale; ds=scale
        else: radius=3; ds=1
        lst=[]
        for j in range(int(math.floor(center-radius))-1, int(math.ceil(center+radius))+2):
            if j<0 or j>=src_n: continue
            w=lancz((center-j)/ds)
            if w!=0: lst.append((j,w))
        ws.append(lst)
    return ws
def apply1d(vals, lst):
    total=sum(w*vals[j] for j,w in lst); ws=sum(w for j,w in lst)
    return total/ws
def clamp_round(v, mode):
    if mode=="round": v=max(0,min(255,v)); return int(math.floor(v+0.5))
    if mode=="trunc": v=max(0,min(255,v)); return int(v)
    if mode=="floor": return int(math.floor(max(0,min(255,v))))
    return v

def resize(src,dw,dh, order="HV", intermediate=None, final="round", float32=False):
    import struct
    def f32(x): return struct.unpack('f', struct.pack('f', x))[0] if float32 else x
    h=len(src); w=len(src[0])
    cur=src
    def pass_dim(cur, dst_w, dst_h):
        # either change width or height
        cur_h=len(cur); cur_w=len(cur[0])
        if dst_w!=cur_w:
            W=weights(cur_w,dst_w)
            out=[]
            for row in cur:
                newrow=[]
                for lst in W:
                    pix=[]
                    for c in range(3):
                        vals=[row[j][c] for j in range(cur_w)]
                        v=apply1d(vals,lst)
                        if intermediate: v=clamp_round(v,intermediate)
                        else: v=f32(v)
                        pix.append(v)
                    newrow.append(tuple(pix))
                out.append(newrow)
            return out
        else:
            H=weights(cur_h,dst_h)
            out=[[None]*cur_w for _ in range(dst_h)]
            for x in range(cur_w):
                for yi,lst in enumerate(H):
                    pix=[]
                    for c in range(3):
                        vals=[cur[j][x][c] for j in range(cur_h)]
                        v=apply1d(vals,lst)
                        if intermediate: v=clamp_round(v,intermediate)
                        else: v=f32(v)
                        pix.append(v)
                    out[yi][x]=tuple(pix)
            return out
    if order=="HV":
        cur=pass_dim(cur,dw,h)
        cur=pass_dim(cur,dw,dh)
    else:
        cur=pass_dim(cur,w,dh)
        cur=pass_dim(cur,dw,dh)
    # final rounding
    return [[tuple(clamp_round(v,final) for v in pix) for pix in row] for row in cur]

