from make_png import write_png
bits={(0,0):0,(1,0):3,(0,1):1,(1,1):4,(0,2):2,(1,2):5,(0,3):6,(1,3):7}
def decode2(out):
    lines=out.rstrip("\n").split("\n"); grid=[]
    for line in lines:
        rows=[[0]*(len(line)*2) for _ in range(4)]
        for i,ch in enumerate(line):
            code=ord(ch)-0x2800
            for (x,y),b in bits.items(): rows[y][i*2+x]=1 if (code>>b)&1 else 0
        grid.extend(rows)
    return grid
def observed(v,w,h):
    pix=[[(v,v,v,255)]*w for _ in range(h)]
    write_png("/tmp/br.png",w,h,pix)
    r=subprocess.run(["./executable","-b","-d",f"{w//2},{h//4}","--dither","/tmp/br.png"], capture_output=True)
    return decode2(r.stdout.decode())

def lin(v):
    s=v/255.0
    return s/12.92 if s<=0.04045 else ((s+0.055)/1.055)**2.4
def fs_linear(v,w,h, coeff="fs", threshold=0.5):
    a=[[lin(v) for _ in range(w)] for __ in range(h)]
    out=[[0]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            old=a[y][x]
            new=1.0 if old>=threshold else 0.0
            out[y][x]=int(new)
            err=old-new
            if coeff=="fs":
                neigh=[(1,0,7/16),( -1,1,3/16),(0,1,5/16),(1,1,1/16)]
            elif coeff=="atkinson":
                neigh=[(1,0,1/8),(2,0,1/8),(-1,1,1/8),(0,1,1/8),(1,1,1/8),(0,2,1/8)]
            for dx,dy,wgt in neigh:
                nx,ny=x+dx,y+dy
                if 0<=nx<w and ny<h: a[ny][nx]+=err*wgt
    return out

for v in [64,100,128,150,192,224]:
    obs=observed(v,16,16)
    for coeff in ["fs","atkinson"]:
        sim=fs_linear(v,16,16,coeff)
        diff=sum(1 for y in range(16) for x in range(16) if obs[y][x]!=sim[y][x])
        print(f"v={v} coeff={coeff} diff {diff}/256 obs_on={sum(sum(r) for r in obs)} sim_on={sum(sum(r) for r in sim)}")
    print("obs")
    for row in obs: print(''.join('#' if x else '.' for x in row))
    print("fs sim")
    sim=fs_linear(v,16,16,"fs")
    for row in sim: print(''.join('#' if x else '.' for x in row))
    print()
