sys.path.insert(0,"/tmp")
exec(open("/tmp/fs_models.py").read().split('models=')[0])

def f32(x): return struct.unpack('f', struct.pack('f', x))[0]
def simulate(v,w,h,variant):
    # variant options: clamp_before, clamp_store, float32, no_clamp
    a=[[lin(v) for _ in range(w)] for __ in range(h)]
    if variant=="float32":
        a=[[f32(lin(v)) for _ in range(w)] for __ in range(h)]
    out=[[0]*w for _ in range(h)]
    for y in range(h):
        for x in range(w):
            old=a[y][x]
            if variant=="clamp_before": old=max(0,min(1,old))
            if variant=="float32": old=f32(old)
            new=1.0 if old>=0.5 else 0.0
            out[y][x]=int(new)
            err=old-new
            if variant=="float32": err=f32(err)
            for dx,dy,wgt in [(1,0,7/16),(-1,1,3/16),(0,1,5/16),(1,1,1/16)]:
                nx,ny=x+dx,y+dy
                if 0<=nx<w and ny<h:
                    val=a[ny][nx]+err*wgt
                    if variant=="float32": val=f32(f32(a[ny][nx])+f32(err*wgt))
                    if variant=="clamp_store": val=max(0,min(1,val))
                    a[ny][nx]=val
    return out

for variant in ["no_clamp","clamp_before","clamp_store","float32"]:
    totaldiff=0; print(variant)
    for v in [32,64,90,100,128,150,170,192,200,224]:
        obs=observed_color([[(v,v,v)]*16 for _ in range(16)],8,4)
        sim=simulate(v,16,16,variant)
        diff=sum(1 for y in range(16) for x in range(16) if obs[y][x]!=sim[y][x])
        print(v,diff, end='; ')
        totaldiff+=diff
    print("\n total",totaldiff)
