{"command":"mkdir -p /tmp/gen && cat > /tmp/gen/main.go << 'GO'
package main

import (
 "image"
 "image/color"
 "image/gif"
 "image/jpeg"
 "image/png"
 "os"
)
func main(){
 // pattern 8x8: left white right black
 img:=image.NewRGBA(image.Rect(0,0,8,8))
 for y:=0;y<8;y++{ for x:=0;x<8;x++{ if x<4 { img.Set(x,y,color.White)} else {img.Set(x,y,color.Black)} } }
 f,_:=os.Create("/tmp/test.jpg"); jpeg.Encode(f,img,&jpeg.Options{Quality:100}); f.Close()
 f,_=os.Create("/tmp/test.png"); png.Encode(f,img); f.Close()
 // single gif
 f,_=os.Create("/tmp/single.gif"); gif.Encode(f,img); f.Close()
 // animated gif 2 frames: frame1 all white, frame2 all black, delay 50 (500ms?), loop 0
 p:=color.Palette{color.White, color.Black}
 frame1:=image.NewPaletted(image.Rect(0,0,8,8),p)
 frame2:=image.NewPaletted(image.Rect(0,0,8,8),p)
 for y:=0;y<8;y++{for x:=0;x<8;x++{ frame1.SetColorIndex(x,y,0); frame2.SetColorIndex(x,y,1)}}
 g:=&gif.GIF{Image:[]*image.Paletted{frame1,frame2}, Delay:[]int{20,20}, LoopCount:0}
 f,_=os.Create("/tmp/anim.gif"); gif.EncodeAll(f,g); f.Close()
 // animated with delays/loops varied etc later
}
