import subprocess, os, shutil, sys
sys.path.insert(0,"/tmp")
from make_png import write_png
BASE="/tmp/save_names"
shutil.rmtree(BASE, ignore_errors=True); os.makedirs(BASE)
def make(name):
    path=os.path.join(BASE,name)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    write_png(path,4,4,[[(255,255,255,255)]*4 for _ in range(4)])
    return name
def run(name, flags=["--save-txt"]):
    for f in []: pass
    # clean generated?
    before=set()
    for root,_,fs in os.walk(BASE):
        for fn in fs: before.add(os.path.join(root,fn))
    args=["-d","2,1","--only-save","--save-txt",".",name]
    r=subprocess.run(["/workspace/executable"]+args, capture_output=True, cwd=BASE)
    after=set()
    for root,_,fs in os.walk(BASE):
        for fn in fs: after.add(os.path.join(root,fn))
    new=sorted(after-before)
    print(name, r.stdout, "new", [os.path.relpath(x,BASE) for x in new])
    for x in new: os.remove(x)

for n in ["a.png","a.b.png","a",".hidden.png",".hidden","A.PNG","archive.tar.gz","a.jpg","a.jpeg","a.bmp","dir/sub.png"]:
    make(n); run(n)
