     } else {
       // count unique
       _=r; _=g; _=bl; _=a
     }
   }
 }
 if len(os.Args)<=2 || os.Args[2]!="dump" {
   // unique colors map
   m:=map[string]int{}
   for y:=b.Min.Y; y<b.Max.Y; y++ { for x:=b.Min.X; x<b.Max.X; x++ { r,g,bl,a:=img.At(x,y).RGBA(); k:=fmt.Sprintf("%d,%d,%d,%d",r>>8,g>>8,bl>>8,a>>8); m[k]++ } }
   for k,v:=range m { fmt.Println(k,v) }
 }
}
