# Use gifdump output pattern (#/+/.) to estimate glyph groups: bounding box of non-dot
def analyze(path):
    out=subprocess.run(["/tmp/gifdump_bin",path], capture_output=True, text=True).stdout.splitlines()
    print(out[0])
    frames=[]
    cur=None
    for line in out[1:]:
