            if cur: frames.append(cur)
            cur=[]; print(line)
        else:
            cur.append(line)
    if cur: frames.append(cur)
    for i,grid in enumerate(frames):
        pts=[(x,y) for y,row in enumerate(grid) for x,ch in enumerate(row) if ch!='.']
