package main
import ("image";"image/color";"image/gif";"os")
func mk(path string, frames []*image.Paletted, disposal []byte){
 g:=&gif.GIF{Image:frames,Delay:[]int{10,10},LoopCount:1, Disposal:disposal, Config: image.Config{Width:8,Height:8}}
 out,_:=os.Create(path); gif.EncodeAll(out,g); out.Close()
}
func main(){
 p:=color.Palette{color.White, color.Black}
 pt:=color.Palette{color.White, color.Black, color.Transparent}
 fullT:=image.NewPaletted(image.Rect(0,0,8,8),pt)
 // all white except one transparent pixel index2
 fullT.SetColorIndex(0,0,2)
 full:=image.NewPaletted(image.Rect(0,0,8,8),p)
 mk("/tmp/transp.gif", []*image.Paletted{full, fullT}, []byte{gif.DisposalNone, gif.DisposalNone})
 mk("/tmp/transp_first.gif", []*image.Paletted{fullT, full}, []byte{gif.DisposalNone, gif.DisposalNone})
 // offset full size (bounds min non-zero but size = 8x8)
 off:=image.NewPaletted(image.Rect(2,2,10,10),p)
 mk("/tmp/offsetfull.gif", []*image.Paletted{full, off}, []byte{gif.DisposalNone, gif.DisposalNone})
 // smaller height only
 smallh:=image.NewPaletted(image.Rect(0,0,8,4),p)
 mk("/tmp/smallh.gif", []*image.Paletted{full, smallh}, []byte{gif.DisposalNone, gif.DisposalNone})
 // first frame smaller
 mk("/tmp/smallfirst.gif", []*image.Paletted{smallh, full}, []byte{gif.DisposalNone, gif.DisposalNone})
}
