import subprocess, sys
sys.path.insert(0,"/tmp")
from make_png import write_png
def dim(w,h,W=None,H=None,d=None):
    write_png("/tmp/sz.png",w,h,[[(255,255,255,255)]*w for _ in range(h)])
    args=[]
    if W is not None: args+=["-W",str(W)]
    if H is not None: args+=["-H",str(H)]
    if d: args+=["-d",d]
    r=subprocess.run(["/workspace/executable"]+args+["/tmp/sz.png"], capture_output=True)
    out=r.stdout.decode()
    lines=out.rstrip("\n").split("\n") if out else []
    return (len(lines[0]) if lines and lines[0] else 0, len(lines) if out else 0, r.returncode, r.stderr[:60])
for (w,h) in [(100,1),(1000,1),(10,1),(3,1)]:
