	{"dither", 0, kindBool},
	{"grayscale", 'g', kindBool},
	{"complex", 'c', kindBool},
	{"full", 'f', kindBool},
	{"negative", 'n', kindBool},
	{"flipX", 'x', kindBool},
	{"flipY", 'y', kindBool},
	{"save-img", 's', kindString},
	{"save-txt", 0, kindString},
	{"save-gif", 0, kindString},
	{"save-bg", 0, kindIntSlice},
	{"font", 0, kindString},
	{"font-color", 0, kindIntSlice},
	{"only-save", 0, kindBool},
	{"formats", 0, kindBool},
	{"help", 'h', kindBool},
	{"version", 'v', kindBool},
}

func findLong(name string) *flagDef {
	for _, d := range flagDefs {
		if d.name == name {
			return d
		}
	}
	return nil
}
func findShort(c byte) *flagDef {
	for _, d := range flagDefs {
		if d.shorthand == c && c != 0 {
			return d
		}
	}
	return nil
}

// state for int slice "changed" handling (first set replaces, rest append)
type parseState struct {
	changed map[string]bool
}

func invalidArg(value string, def *flagDef, err error) error {
	return fmt.Errorf("invalid argument %q for %q flag: %v", value, def.display(), err)
}

func (f *flags) setValue(def *flagDef, value string, st *parseState) error {
	switch def.kind {
	case kindBool:
		v, err := strconv.ParseBool(value)
		if err != nil {
			return invalidArg(value, def, err)
		}
		f.setBool(def.name, v)
		return nil
	case kindInt:
		v, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return invalidArg(value, def, err)
		}
		f.setInt(def.name, int(v))
		return nil
	case kindString:
		f.setString(def.name, value)
		return nil
	case kindIntSlice:
		parts := strings.Split(value, ",")
		vals := make([]int, 0, len(parts))
		for _, p := range parts {
			v, err := strconv.Atoi(p)
			if err != nil {
				return invalidArg(value, def, err)
			}
			vals = append(vals, v)
		}
		f.setIntSlice(def.name, vals, st)
		return nil
	}
	return nil
}

func (f *flags) setBool(name string, v bool) {
	switch name {
	case "color":
		f.color = v
	case "color-bg":
		f.colorBg = v
	case "braille":
		f.braille = v
	case "dither":
		f.dither = v
	case "grayscale":
		f.grayscale = v
	case "complex":
		f.complex = v
	case "full":
		f.full = v
	case "negative":
		f.negative = v
	case "flipX":
		f.flipX = v
	case "flipY":
		f.flipY = v
	case "only-save":
		f.onlySave = v
	case "formats":
		f.formats = v
	case "help":
		f.help = v
	case "version":
		f.version = v
	}
}
func (f *flags) setInt(name string, v int) {
	switch name {
	case "width":
		f.width = v
	case "height":
		f.height = v
	case "threshold":
		f.threshold = v
	}
}
func (f *flags) setString(name string, v string) {
	switch name {
	case "map":
		f.customMap = v
	case "save-img":
		f.saveImg = v
	case "save-txt":
		f.saveTxt = v
	case "save-gif":
		f.saveGif = v
	case "font":
		f.font = v
	}
}
func (f *flags) setIntSlice(name string, vals []int, st *parseState) {
	var ptr *[]int
	switch name {
	case "dimensions":
		ptr = &f.dimensions
	case "save-bg":
		ptr = &f.saveBg
	case "font-color":
		ptr = &f.fontColor
	default:
		return
	}
	if !st.changed[name] {
		*ptr = vals
		st.changed[name] = true
	} else {
		*ptr = append(*ptr, vals...)
	}
}

func parseArgs(argv []string) (*flags, []string, error) {
	fl := &flags{}
	st := &parseState{changed: map[string]bool{}}
	var positional []string
	i := 0
	terminated := false
	for i < len(argv) {
		arg := argv[i]
		i++
		if terminated {
			positional = append(positional, arg)
			continue
		}
		if arg == "--" {
			terminated = true
			continue
		}
		if strings.HasPrefix(arg, "--") {
			// long flag, arg != "--" here
			nameVal := arg[2:]
			if nameVal == "" || nameVal[0] == '-' || nameVal[0] == '=' {
				return nil, nil, fmt.Errorf("bad flag syntax: %s", arg)
			}
			name := nameVal
			value := ""
			hasValue := false
			if idx := strings.Index(nameVal, "="); idx >= 0 {
				name = nameVal[:idx]
				value = nameVal[idx+1:]
				hasValue = true
			}
			def := findLong(name)
			if def == nil {
				return nil, nil, fmt.Errorf("unknown flag: --%s", name)
			}
			if def.kind == kindBool {
				if !hasValue {
					value = "true"
				}
				if err := fl.setValue(def, value, st); err != nil {
					return nil, nil, err
				}
			} else {
				if !hasValue {
					if i >= len(argv) {
						return nil, nil, fmt.Errorf("flag needs an argument: --%s", name)
					}
					value = argv[i]
					i++
				}
				if err := fl.setValue(def, value, st); err != nil {
					return nil, nil, err
				}
			}
			continue
		}
		if strings.HasPrefix(arg, "-") && arg != "-" {
			shorthands := arg[1:]
			for len(shorthands) > 0 {
				c := shorthands[0]
				def := findShort(c)
				if def == nil {
					return nil, nil, fmt.Errorf("unknown shorthand flag: %q in -%s", rune(c), shorthands)
				}
				if def.kind == kindBool {
					if len(shorthands) > 2 && shorthands[1] == '=' {
						value := shorthands[2:]
						if err := fl.setValue(def, value, st); err != nil {
							return nil, nil, err
						}
						shorthands = ""
					} else if len(shorthands) > 1 {
						// set true, continue with next shorthand
						if err := fl.setValue(def, "true", st); err != nil {
							return nil, nil, err
						}
						shorthands = shorthands[1:]
					} else {
						if err := fl.setValue(def, "true", st); err != nil {
							return nil, nil, err
						}
						shorthands = ""
					}
				} else {
					// needs a value
					if len(shorthands) > 2 && shorthands[1] == '=' {
						value := shorthands[2:]
						if err := fl.setValue(def, value, st); err != nil {
							return nil, nil, err
						}
						shorthands = ""
					} else if len(shorthands) > 1 {
						value := shorthands[1:]
						if err := fl.setValue(def, value, st); err != nil {
							return nil, nil, err
						}
						shorthands = ""
					} else if i < len(argv) {
						value := argv[i]
						i++
						if err := fl.setValue(def, value, st); err != nil {
							return nil, nil, err
						}
						shorthands = ""
					} else {
						return nil, nil, fmt.Errorf("flag needs an argument: %q in -%s", rune(c), shorthands)
					}
				}
			}
			continue
		}
		// positional
		positional = append(positional, arg)
	}
	return fl, positional, nil
}

func fatalParseError(err error) {
	// Cobra prints the error plus usage to stderr, and Execute() in the
	// original also prints it to stdout, exiting with code 1.
	fmt.Fprintln(os.Stderr, "Error:", err.Error())
	fmt.Fprint(os.Stderr, usageText)
	fmt.Fprintln(os.Stderr)
	fmt.Println(err.Error())
	os.Exit(1)
}
GO"}

