package main

import (
	"image"
	"image/color"
	"image/draw"
	"math"
)

// Convert any image to a premultiplied RGBA image with origin (0,0),
// using the same colour conversion as colour.RGBAModel (RGBA() >> 8).
func toRGBA(src image.Image) *image.RGBA {
	b := src.Bounds()
	w, h := b.Dx(), b.Dy()
	if w < 0 {
		w = 0
	}
	if h < 0 {
		h = 0
	}
	dst := image.NewRGBA(image.Rect(0, 0, w, h))
	draw.Draw(dst, dst.Bounds(), src, b.Min, draw.Src)
	return dst
}

func sinc(x float64) float64 {
	if x == 0 {
		return 1
	}
	x *= math.Pi
	return math.Sin(x) / x
}

func lanczos3(x float64) float64 {
	if x == 0 {
		return 1
	}
	if x <= -3 || x >= 3 {
		return 0
	}
	return sinc(x) * sinc(x/3)
}

type resizeCoeff struct {
	idx    int
	weight float64
}

func resizeCoeffs(srcN, dstN int) [][]resizeCoeff {
	scale := float64(srcN) / float64(dstN)
	coeffs := make([][]resizeCoeff, dstN)
	for i := 0; i < dstN; i++ {
		center := (float64(i)+0.5)*scale - 0.5
		var radius, step float64
		if scale > 1 {
			radius = 3 * scale
			step = scale
		} else {
			radius = 3
			step = 1
		}
		start := int(math.Floor(center - radius))
		end := int(math.Ceil(center + radius))
		var list []resizeCoeff
		sum := 0.0
		type cw struct {
			j int
			w float64
		}
		var tmp []cw
		for j := start; j <= end; j++ {
			if j < 0 || j >= srcN {
				continue
			}
			w := lanczos3((center - float64(j)) / step)
			if w == 0 {
				continue
			}
			tmp = append(tmp, cw{j, w})
			sum += w
		}
		for _, t := range tmp {
			_ = t
			list = append(list, resizeCoeff{idx: t.j, weight: t.w})
		}
		// store sum in a sentinel by normalising later in caller via recompute;
		// instead normalise weights here:
		if sum != 0 {
			for k := range list {
				list[k].weight /= sum
			}
		}
		coeffs[i] = list
	}
	return coeffs
}

func clampRound(v float64) uint8 {
	if v < 0 {
		v = 0
	}
	if v > 255 {
		v = 255
	}
	return uint8(math.Floor(v + 0.5))
}

// resizeImage resizes an RGBA image using two Lanczos3 passes
// (horizontal first), rounding/clamping after each pass -- matching the
// behaviour observed from the original tool.
func resizeImage(src *image.RGBA, dstW, dstH int) *image.RGBA {
	if dstW <= 0 || dstH <= 0 {
		return image.NewRGBA(image.Rectangle{})
	}
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	if srcW <= 0 || srcH <= 0 {
		return image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	}
	// Horizontal pass: srcW -> dstW, keep height.
	tmp := src
	if dstW != srcW || true {
		coeffs := resizeCoeffs(srcW, dstW)
		inter := image.NewRGBA(image.Rect(0, 0, dstW, srcH))
		for y := 0; y < srcH; y++ {
			srcOff := y * src.Stride
			dstOff := y * inter.Stride
			for x := 0; x < dstW; x++ {
				var r, g, b, a float64
				for _, c := range coeffs[x] {
					off := srcOff + c.idx*4
					w := c.weight
					r += float64(src.Pix[off+0]) * w
					g += float64(src.Pix[off+1]) * w
					b += float64(src.Pix[off+2]) * w
					a += float64(src.Pix[off+3]) * w
				}
				doff := dstOff + x*4
				inter.Pix[doff+0] = clampRound(r)
				inter.Pix[doff+1] = clampRound(g)
				inter.Pix[doff+2] = clampRound(b)
				inter.Pix[doff+3] = clampRound(a)
			}
		}
		tmp = inter
	}
	// Vertical pass
	if dstH != srcH || true {
		coeffs := resizeCoeffs(srcH, dstH)
		out := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
		for x := 0; x < dstW; x++ {
			for y := 0; y < dstH; y++ {
				var r, g, b, a float64
				for _, c := range coeffs[y] {
					off := c.idx*tmp.Stride + x*4
					w := c.weight
					r += float64(tmp.Pix[off+0]) * w
					g += float64(tmp.Pix[off+1]) * w
					b += float64(tmp.Pix[off+2]) * w
					a += float64(tmp.Pix[off+3]) * w
				}
				doff := y*out.Stride + x*4
				out.Pix[doff+0] = clampRound(r)
				out.Pix[doff+1] = clampRound(g)
				out.Pix[doff+2] = clampRound(b)
				out.Pix[doff+3] = clampRound(a)
			}
		}
		return out
	}
	return tmp
}

var _ = color.RGBA{}
