					w := c.weight
					r += float64(tmp.Pix[off+0]) * w
					g += float64(tmp.Pix[off+1]) * w
					b += float64(tmp.Pix[off+2]) * w
					a += float64(tmp.Pix[off+3]) * w
				}
				doff := y*out.Stride + x*4
				out.Pix[doff+0] = clampRound(r)
