package main

import (
	"encoding/binary"
	"errors"
	"image"
	"image/color"
	"io"
)

func decodeBMP(r io.Reader) (image.Image, error) {
	data, err := io.ReadAll(r)
	if err != nil {
		return nil, err
	}
	if len(data) < 26 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	off := int(binary.LittleEndian.Uint32(data[10:14]))
	headerSize := int(binary.LittleEndian.Uint32(data[14:18]))
	if headerSize == 12 {
		// BITMAPCOREHEADER
		w := int(binary.LittleEndian.Uint16(data[18:20]))
		h := int(binary.LittleEndian.Uint16(data[20:22]))
		planes := binary.LittleEndian.Uint16(data[22:24])
		bpp := int(binary.LittleEndian.Uint16(data[24:26]))
		if planes != 1 || w <= 0 || h <= 0 {
			return nil, errors.New("bmp: unsupported BMP image")
		}
		return readBMPData(data, off, w, h, bpp, nil)
	}
	if headerSize < 40 || len(data) < 14+headerSize {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	w := int(int32(binary.LittleEndian.Uint32(data[18:22])))
	hRaw := int(int32(binary.LittleEndian.Uint32(data[22:26])))
	topDown := false
	h := hRaw
	if h < 0 {
		topDown = true
		h = -h
	}
	bpp := int(binary.LittleEndian.Uint16(data[28:30]))
	compression := binary.LittleEndian.Uint32(data[30:34])
	if compression != 0 && compression != 3 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	if w <= 0 || h <= 0 {
		return nil, errors.New("bmp: unsupported BMP image")
	}
	var palette []color.RGBA
	if bpp <= 8 {
		colorsUsed := 0
		if headerSize >= 40+4 {
			colorsUsed = int(binary.LittleEndian.Uint32(data[46:50]))
		}
		if colorsUsed == 0 {
			colorsUsed = 1 << uint(bpp)
		}
		palOff := 14 + headerSize
		for i := 0; i < colorsUsed; i++ {
			if palOff+4*i+4 > len(data) {
				break
			}
			b := data[palOff+4*i+0]
			g := data[palOff+4*i+1]
			rr := data[palOff+4*i+2]
			palette = append(palette, color.RGBA{rr, g, b, 255})
		}
	}
	img, err := readBMPDataEx(data, off, w, h, bpp, palette, topDown)
	return img, err
}

func readBMPData(data []byte, off, w, h, bpp int, palette []color.RGBA) (image.Image, error) {
	return readBMPDataEx(data, off, w, h, bpp, palette, false)
}

func readBMPDataEx(data []byte, off, w, h, bpp int, palette []color.RGBA, topDown bool) (image.Image, error) {
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	// row stride in bytes padded to 4-byte multiple
	bitsPerRow := w * bpp
	if bpp < 8 {
		bitsPerRow = w * bpp
	}
	stride := ((bitsPerRow + 31) / 32) * 4
	for y := 0; y < h; y++ {
		srcY := y
		if !topDown {
			srcY = h - 1 - y
		}
		rowOff := off + srcY*stride
		for x := 0; x < w; x++ {
			var c color.RGBA
			c.A = 255
			switch bpp {
			case 24:
				p := rowOff + x*3
				if p+3 > len(data) {
					continue
				}
				c.B = data[p]
				c.G = data[p+1]
				c.R = data[p+2]
			case 32:
				p := rowOff + x*4
				if p+4 > len(data) {
					continue
				}
				c.B = data[p]
				c.G = data[p+1]
				c.R = data[p+2]
				// x/image/bmp keeps 32-bit images opaque unless an alpha
				// channel is meaningful; observed behaviour treats the
				// stored alpha as the pixel alpha for RGBA output via
				// premultiplication in later stages. Use stored alpha if
				// any pixel has non-opaque alpha is complex; mirror common
				// decoders: keep alpha byte.
				c.A = data[p+3]
				if c.A == 0 {
					// Many BMPs leave this byte as 0 padding; the reference
					// (x/image/bmp) treats 32bpp BMPs as opaque.
					c.A = 255
					c.R, c.G, c.B = data[p+2], data[p+1], data[p]
					// the above already assigned; restore
					c.R = data[p+2]
					c.G = data[p+1]
					c.B = data[p]
				}
			case 8:
				p := rowOff + x
				if p >= len(data) {
					continue
				}
				idx := int(data[p])
				if idx < len(palette) {
					c = palette[idx]
				}
			case 4:
				p := rowOff + x/2
				if p >= len(data) {
					continue
				}
				var idx int
				if x%2 == 0 {
					idx = int(data[p] >> 4)
				} else {
					idx = int(data[p] & 0x0F)
				}
				if idx < len(palette) {
					c = palette[idx]
				}
			case 1:
				p := rowOff + x/8
				if p >= len(data) {
					continue
				}
				bit := (data[p] >> (7 - uint(x%8))) & 1
				idx := int(bit)
				if idx < len(palette) {
					c = palette[idx]
				} else if bit == 1 {
					c = color.RGBA{255, 255, 255, 255}
				}
			case 16:
				p := rowOff + x*2
				if p+2 > len(data) {
					continue
				}
				v := binary.LittleEndian.Uint16(data[p : p+2])
				// 5-5-5
				r5 := (v >> 10) & 0x1F
				g5 := (v >> 5) & 0x1F
				b5 := v & 0x1F
				c.R = uint8((r5 << 3) | (r5 >> 2))
				c.G = uint8((g5 << 3) | (g5 >> 2))
				c.B = uint8((b5 << 3) | (b5 >> 2))
			default:
				return nil, errors.New("bmp: unsupported BMP image")
			}
			img.SetRGBA(x, y, c)
		}
	}
	return img, nil
}
