					idx = int(data[p] >> 4)
				} else {
					idx = int(data[p] & 0x0F)
				}
				if idx < len(palette) {
					c = palette[idx]
				}
			case 1:
				p := rowOff + x/8
				if p >= len(data) {
					continue
				}
				bit := (data[p] >> (7 - uint(x%8))) & 1
				idx := int(bit)
				if idx < len(palette) {
					c = palette[idx]
				} else if bit == 1 {
					c = color.RGBA{255, 255, 255, 255}
				}
			case 16:
				p := rowOff + x*2
				if p+2 > len(data) {
					continue
				}
				v := binary.LittleEndian.Uint16(data[p : p+2])
				// 5-5-5
				r5 := (v >> 10) & 0x1F
				g5 := (v >> 5) & 0x1F
				b5 := v & 0x1F
				c.R = uint8((r5 << 3) | (r5 >> 2))
				c.G = uint8((g5 << 3) | (g5 >> 2))
				c.B = uint8((b5 << 3) | (b5 >> 2))
			default:
				return nil, errors.New("bmp: unsupported BMP image")
			}
			img.SetRGBA(x, y, c)
		}
	}
	return img, nil
}
