func packBitsDecode(data []byte) []byte {
	var out []byte
	i := 0
	for i < len(data) {
		n := int(int8(data[i]))
		i++
		if n >= 0 {
			for j := 0; j <= n && i < len(data); j++ {
				out = append(out, data[i])
				i++
			}
		} else if n >= -127 {
			if i >= len(data) {
				break
			}
			b := data[i]
			i++
			for j := 0; j < 1-n; j++ {
				out = append(out, b)
			}
		}
		// n==-128 no-op
	}
	return out
}

// TIFF LZW decoding (MSB-first, EarlyChange=1)
func lzwDecode(data []byte) ([]byte, error) {
	// bit reader MSB first
	bitPos := 0
	readCode := func(width uint) (int, bool) {
		if bitPos+int(width) > len(data)*8 {
			return 0, false
		}
		val := 0
		for k := 0; k < int(width); k++ {
			byteIdx := (bitPos + k) / 8
			bitIdx := 7 - uint((bitPos+k)%8)
			val = (val << 1) | int((data[byteIdx]>>bitIdx)&1)
		}
		bitPos += int(width)
		return val, true
	}
	const clearCode = 256
	const eoiCode = 257
	table := make([][]byte, 4096)
	reset := func() {
		for i := 0; i < 256; i++ {
			table[i] = []byte{byte(i)}
		}
		for i := 256; i < 4096; i++ {
			table[i] = nil
		}
	}
	reset()
	nextCode := 258
	codeWidth := uint(9)
	var old []byte
	var out []byte
	for {
		code, ok := readCode(codeWidth)
		if !ok {
			break
		}
		if code == clearCode {
			reset()
			nextCode = 258
			codeWidth = 9
			old = nil
			continue
		}
		if code == eoiCode {
			break
		}
		var entry []byte
		if code < nextCode && table[code] != nil {
			entry = table[code]
		} else if code == nextCode && old != nil {
			entry = append(append([]byte{}, old...), old[0])
		} else {
			return nil, errors.New("tiff: invalid LZW code")
		}
		out = append(out, entry...)
		if old != nil && nextCode < 4096 {
			newEntry := append(append([]byte{}, old...), entry[0])
			table[nextCode] = newEntry
			nextCode++
			// EarlyChange: increase width when nextCode reaches (1<<width)-1
			if nextCode == (1<<codeWidth)-1 && codeWidth < 12 {
				codeWidth++
			}
		}
		old = entry
	}
	return out, nil
}
