package main

import (
	"fmt"
	"image"
	"image/color"
	"math"
	"os"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

const defaultChars = " .:-=+*#%@"
const complexChars = " .'`^\" ,:;Il!i><~+_-?][}{1)(|\\/tfjrxnuvczXYUJCLQ0OZmwqpdbkhao*#MW&8%B@$"

func getTerminalSize() (int, int) {
	type winsize struct {
		Rows, Cols, X, Y uint16
	}
	ws := &winsize{}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdin.Fd(), uintptr(syscall.TIOCGWINSZ), uintptr(unsafe.Pointer(ws)))
	if errno != 0 {
		return 0, 0
	}
	return int(ws.Cols), int(ws.Rows)
}

func calcHeightFromWidth(w, imgW, imgH int) int {
	if imgW == 0 {
		return 0
	}
	h := int(float64(w) * float64(imgH) / float64(imgW) / 2)
	if h == 0 && w > 0 {
		h = 1
	}
	return h
}
func calcWidthFromHeight(h, imgW, imgH int) int {
	if imgH == 0 {
		return 0
	}
	w := int(float64(h)*float64(imgW)/float64(imgH)) * 2
	if w == 0 && h > 0 {
		w = 1
	}
	return w
}

// charDimensions decides ascii/braille character dimensions.
func charDimensions(imgW, imgH int, fl *flags) (int, int) {
	if fl.full {
		tw, _ := getTerminalSize()
		w := tw - 1
		h := calcHeightFromWidth(w, imgW, imgH)
		return w, h
	}
	if len(fl.dimensions) == 2 {
		return fl.dimensions[0], fl.dimensions[1]
	}
	if fl.width != 0 {
		return fl.width, calcHeightFromWidth(fl.width, imgW, imgH)
	}
	if fl.height != 0 {
		return calcWidthFromHeight(fl.height, imgW, imgH), fl.height
	}
	tw, th := getTerminalSize()
	h := th - 1
	w := calcWidthFromHeight(h, imgW, imgH)
	if w > tw-1 {
		w = tw - 1
		h = calcHeightFromWidth(w, imgW, imgH)
	}
	return w, h
}

// colour support

func terminalColorType() string {
	if ct := os.Getenv("COLORTERM"); ct != "" {
		if strings.Contains(ct, "truecolor") || strings.Contains(ct, "24bit") {
			return "truecolor"
		}
		return ""
	}
	if fc := os.Getenv("FORCE_COLOR"); fc != "" {
		return ""
	}
	switch os.Getenv("TERM_PROGRAM") {
	case "Hyper":
		return "truecolor"
	case "iTerm.app":
		ver := os.Getenv("TERM_PROGRAM_VERSION")
		majorStr := strings.Split(ver, ".")[0]
		major := -1
		if majorStr != "" {
			if v, err := parseSimpleInt(majorStr); err == nil {
				major = v
			}
		}
		if major == 3 {
			return "truecolor"
		}
		return "256"
	case "Apple_Terminal":
		return "256"
	}
	term := os.Getenv("TERM")
	if strings.Contains(term, "256color") || strings.Contains(term, "xterm") || term == "screen" {
		return "256"
	}
	return ""
}

func parseSimpleInt(s string) (int, error) {
	// strconv.Atoi behaviour
	n := 0
	if s == "" {
		return 0, fmt.Errorf("invalid")
	}
	i := 0
	neg := false
	if s[0] == '+' {
		i = 1
	} else if s[0] == '-' {
		neg = true
		i = 1
	}
