// 8-bit colour conversion
var cubeLevels = []int{0, 95, 135, 175, 215, 255}

func cubeQ(v int) int {
	best := 0
	bestDist := math.MaxInt32
	for i, lv := range cubeLevels {
		d := v - lv
		if d < 0 {
			d = -d
		}
		if d < bestDist || (d == bestDist && i > best) {
			bestDist = d
			best = i
		}
	}
	return best
}

func rgbTo256(r, g, b int) int {
	qr, qg, qb := cubeQ(r), cubeQ(g), cubeQ(b)
	switch {
	case qr == 0 && qg == 0 && qb == 0:
		return 0
	case qr == 5 && qg == 0 && qb == 0:
		return 9
	case qr == 0 && qg == 5 && qb == 0:
		return 10
	case qr == 5 && qg == 5 && qb == 0:
		return 11
	case qr == 0 && qg == 0 && qb == 5:
		return 12
	case qr == 5 && qg == 0 && qb == 5:
		return 13
	case qr == 0 && qg == 5 && qb == 5:
		return 14
	case qr == 5 && qg == 5 && qb == 5:
		return 15
	}
	return 16 + 36*qr + 6*qg + qb
}

