// character table construction replicating the original's byte-index behaviour
func buildCharTable(mapStr string) []string {
	table := make([]string, len(mapStr))
	for i, r := range mapStr {
		table[i] = string(r)
	}
	return table
}

func selectChar(mapStr string, table []string, gray int) string {
	if len(table) == 0 {
		return ""
	}
	runeCount := utf8.RuneCountInString(mapStr)
	if runeCount <= 0 {
		return ""
	}
	idx := gray * runeCount / 255
	if idx >= runeCount {
		idx = runeCount - 1
	}
	if idx < 0 {
		idx = 0
	}
	if idx >= len(table) {
		return ""
	}
	return table[idx]
}

type cell struct {
	char string
	r, g, b int // colour for terminal/save (already mode-resolved)
