// pixel extraction helpers on RGBA images
func pixelRGB(img *image.RGBA, x, y int) (int, int, int) {
	off := img.PixOffset(x, y)
	return int(img.Pix[off]), int(img.Pix[off+1]), int(img.Pix[off+2])
}

func flipRGBA(img *image.RGBA, flipX, flipY bool) *image.RGBA {
	if !flipX && !flipY {
		return img
	}
	w := img.Bounds().Dx()
	h := img.Bounds().Dy()
	out := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := 0; y < h; y++ {
		sy := y
		if flipY {
			sy = h - 1 - y
		}
		for x := 0; x < w; x++ {
			sx := x
			if flipX {
				sx = w - 1 - x
			}
			so := img.PixOffset(sx, sy)
			do := out.PixOffset(x, y)
			copy(out.Pix[do:do+4], img.Pix[so:so+4])
		}
	}
	return out
}

// triggerPanicForZeroDims replicates the original panic for zero-sized output.
func triggerPanicForZeroDims() {
	var empty []string
	_ = empty[0]
}

// convertToArt is the main still/braille conversion for a single image.
// Returns the grid, and a flag whether colour support is required but
// unavailable (colourError).
func convertToArt(src image.Image, fl *flags) (*artGrid, bool) {
	rgba := toRGBA(src)
	b := rgba.Bounds()
	imgW, imgH := b.Dx(), b.Dy()
	charW, charH := charDimensions(imgW, imgH, fl)
	if charW <= 0 || charH <= 0 {
		triggerPanicForZeroDims()
	}
	needColor := colorRequested(fl)
	colorType := ""
	if needColor {
		colorType = terminalColorType()
		if colorType == "" {
			return nil, true
		}
	}
	if fl.braille {
		return convertBraille(rgba, charW, charH, fl, imgW, imgH)
	}
	// ascii
	resized := resizeImage(rgba, charW, charH)
	resized = flipRGBA(resized, fl.flipX, fl.flipY)
	mapStr := defaultChars
	if fl.customMap != "" {
		mapStr = fl.customMap
	} else if fl.complex {
		mapStr = complexChars
	}
	table := buildCharTable(mapStr)
	grid := &artGrid{width: charW, height: charH}
	grid.cells = make([][]cell, charH)
	for y := 0; y < charH; y++ {
		row := make([]cell, charW)
		for x := 0; x < charW; x++ {
			r, g, bl := pixelRGB(resized, x, y)
			er, eg, eb := r, g, bl
			if fl.negative {
				er, eg, eb = 255-er, 255-eg, 255-eb
			}
			gray := grayOf(er, eg, eb)
			ch := selectChar(mapStr, table, gray)
			cr, cg, cb := fl.cellColor(er, eg, eb, gray)
			row[x] = cell{char: ch, r: cr, g: cg, b: cb}
		}
		grid.cells[y] = row
	}
	return grid, false
}

func convertBraille(rgba *image.RGBA, charW, charH int, fl *flags, imgW, imgH int) (*artGrid, bool) {
	pixW := charW * 2
	pixH := charH * 4
	resized := resizeImage(rgba, pixW, pixH)
	// decide dots
	type unit struct {
		sr, sg, sb int // source colour pixel
		dr, dg, db int // decision pixel
	}
	units := make([][]unit, pixH)
	if fl.dither {
		dithered := ditherImage(resized) // RGBA black/white
		for y := 0; y < pixH; y++ {
			row := make([]unit, pixW)
			for x := 0; x < pixW; x++ {
				sr, sg, sb := pixelRGB(resized, x, y)
				dr, dg, db := pixelRGB(dithered, x, y)
				row[x] = unit{sr, sg, sb, dr, dg, db}
			}
			units[y] = row
		}
	} else {
		for y := 0; y < pixH; y++ {
			row := make([]unit, pixW)
			for x := 0; x < pixW; x++ {
				sr, sg, sb := pixelRGB(resized, x, y)
				row[x] = unit{sr, sg, sb, sr, sg, sb}
			}
			units[y] = row
		}
	}
	// flips applied to the dot grid (after any dithering)
	if fl.flipX || fl.flipY {
		flipped := make([][]unit, pixH)
		for y := 0; y < pixH; y++ {
			sy := y
			if fl.flipY {
				sy = pixH - 1 - y
			}
			row := make([]unit, pixW)
			for x := 0; x < pixW; x++ {
				sx := x
				if fl.flipX {
					sx = pixW - 1 - x
				}
				row[x] = units[sy][sx]
			}
			flipped[y] = row
		}
		units = flipped
	}
	threshold := fl.threshold
	if threshold == 0 {
		threshold = 128
	}
	grid := &artGrid{width: charW, height: charH}
	grid.cells = make([][]cell, charH)
	bitFor := func(dx, dy int) uint {
		switch {
		case dx == 0 && dy == 0:
			return 0
		case dx == 1 && dy == 0:
			return 3
		case dx == 0 && dy == 1:
			return 1
		case dx == 1 && dy == 1:
			return 4
		case dx == 0 && dy == 2:
			return 2
		case dx == 1 && dy == 2:
			return 5
		case dx == 0 && dy == 3:
			return 6
		default: // 1,3
			return 7
		}
	}
	for by := 0; by < charH; by++ {
		row := make([]cell, charW)
		for bx := 0; bx < charW; bx++ {
			var bits uint
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					u := units[by*4+dy][bx*2+dx]
					er, eg, eb := u.dr, u.dg, u.db
					if fl.negative {
						er, eg, eb = 255-er, 255-eg, 255-eb
					}
					gray := grayOf(er, eg, eb)
					if gray >= threshold {
						bits |= 1 << bitFor(dx, dy)
					}
				}
			}
			ch := string(rune(0x2800 + int(bits)))
			// colour from top-left unit of the (flipped) block
			tl := units[by*4][bx*2]
			er, eg, eb := tl.sr, tl.sg, tl.sb
			if fl.negative {
				er, eg, eb = 255-er, 255-eg, 255-eb
			}
			gray := grayOf(er, eg, eb)
			cr, cg, cb := fl.cellColor(er, eg, eb, gray)
			row[bx] = cell{char: ch, r: cr, g: cg, b: cb}
		}
		grid.cells[by] = row
	}
	return grid, false
}

func srgbToLinear(s float64) float64 {
	if s <= 0.04045 {
		return s / 12.92
	}
	return math.Pow((s+0.055)/1.055, 2.4)
}

// ditherImage applies Floyd-Steinberg dithering in linear RGB space,
// returning a black/white RGBA image.
func ditherImage(src *image.RGBA) *image.RGBA {
	w := src.Bounds().Dx()
	h := src.Bounds().Dy()
	// linear values [h][w][3]
	vals := make([][][3]float64, h)
	for y := 0; y < h; y++ {
		row := make([][3]float64, w)
		for x := 0; x < w; x++ {
			r, g, b := pixelRGB(src, x, y)
			row[x] = [3]float64{srgbToLinear(float64(r) / 255), srgbToLinear(float64(g) / 255), srgbToLinear(float64(b) / 255)}
		}
		vals[y] = row
	}
	out := image.NewRGBA(image.Rect(0, 0, w, h))
	type nbor struct {
		dx, dy int
		weight float64
	}
	neigh := []nbor{{1, 0, 7.0 / 16}, {-1, 1, 3.0 / 16}, {0, 1, 5.0 / 16}, {1, 1, 1.0 / 16}}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := vals[y][x]
			var distBlack, distWhite float64
			for i := 0; i < 3; i++ {
				distBlack += old[i] * old[i]
				d := 1 - old[i]
				distWhite += d * d
			}
			newVal := 0.0
			if distWhite < distBlack {
				newVal = 1
			}
			off := out.PixOffset(x, y)
			v := uint8(0)
			if newVal == 1 {
				v = 255
			}
			out.Pix[off], out.Pix[off+1], out.Pix[off+2], out.Pix[off+3] = v, v, v, 255
			var err [3]float64
			for i := 0; i < 3; i++ {
				err[i] = old[i] - newVal
			}
			for _, nb := range neigh {
				nx, ny := x+nb.dx, y+nb.dy
				if nx < 0 || nx >= w || ny < 0 || ny >= h {
					continue
				}
				for i := 0; i < 3; i++ {
					nv := vals[ny][nx][i] + err[i]*nb.weight
					if nv < 0 {
						nv = 0
					}
					if nv > 1 {
						nv = 1
					}
					vals[ny][nx][i] = nv
				}
			}
		}
	}
	return out
}
