func calcHeightFromWidth(w, imgW, imgH int) int {
	if imgW == 0 {
		return 0
	}
	h := int(float64(w) * float64(imgH) / float64(imgW) / 2)
	if h == 0 && w > 0 {
		h = 1
	}
	return h
