				dr, dg, db := pixelRGB(dithered, x, y)
				row[x] = unit{sr, sg, sb, dr, dg, db}
			}
			units[y] = row
		}
	} else {
		for y := 0; y < pixH; y++ {
			row := make([]unit, pixW)
			for x := 0; x < pixW; x++ {
				sr, sg, sb := pixelRGB(resized, x, y)
				row[x] = unit{sr, sg, sb, sr, sg, sb}
			}
			units[y] = row
		}
	}
