	}
	threshold := fl.threshold
	if threshold == 0 {
		threshold = 128
	}
	grid := &artGrid{width: charW, height: charH}
	grid.cells = make([][]cell, charH)
	bitFor := func(dx, dy int) uint {
		switch {
		case dx == 0 && dy == 0:
			return 0
		case dx == 1 && dy == 0:
			return 3
		case dx == 0 && dy == 1:
			return 1
		case dx == 1 && dy == 1:
			return 4
		case dx == 0 && dy == 2:
			return 2
		case dx == 1 && dy == 2:
			return 5
		case dx == 0 && dy == 3:
			return 6
		default: // 1,3
			return 7
		}
	}
