		row := make([]cell, charW)
		for bx := 0; bx < charW; bx++ {
			var bits uint
			for dy := 0; dy < 4; dy++ {
				for dx := 0; dx < 2; dx++ {
					u := units[by*4+dy][bx*2+dx]
					er, eg, eb := u.dr, u.dg, u.db
					if fl.negative {
						er, eg, eb = 255-er, 255-eg, 255-eb
					}
