// colour support

func terminalColorType() string {
	if ct := os.Getenv("COLORTERM"); ct != "" {
		if strings.Contains(ct, "truecolor") || strings.Contains(ct, "24bit") {
			return "truecolor"
		}
		return ""
	}
	if fc := os.Getenv("FORCE_COLOR"); fc != "" {
		return ""
	}
	switch os.Getenv("TERM_PROGRAM") {
	case "Hyper":
		return "truecolor"
	case "iTerm.app":
		ver := os.Getenv("TERM_PROGRAM_VERSION")
		majorStr := strings.Split(ver, ".")[0]
		major := -1
		if majorStr != "" {
			if v, err := parseSimpleInt(majorStr); err == nil {
				major = v
			}
		}
		if major == 3 {
			return "truecolor"
		}
		return "256"
	case "Apple_Terminal":
		return "256"
	}
	term := os.Getenv("TERM")
	if strings.Contains(term, "256color") || strings.Contains(term, "xterm") || term == "screen" {
		return "256"
	}
	return ""
}

func parseSimpleInt(s string) (int, error) {
	// strconv.Atoi behaviour
	n := 0
	if s == "" {
		return 0, fmt.Errorf("invalid")
	}
	i := 0
	neg := false
	if s[0] == '+' {
		i = 1
	} else if s[0] == '-' {
		neg = true
		i = 1
	}
	if i >= len(s) {
		return 0, fmt.Errorf("invalid")
	}
	for ; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return 0, fmt.Errorf("invalid")
		}
		n = n*10 + int(s[i]-'0')
	}
	if neg {
		n = -n
	}
	return n, nil
}

// 8-bit colour conversion
var cubeLevels = []int{0, 95, 135, 175, 215, 255}

func cubeQ(v int) int {
	best := 0
	bestDist := math.MaxInt32
	for i, lv := range cubeLevels {
		d := v - lv
		if d < 0 {
			d = -d
		}
		if d < bestDist || (d == bestDist && i > best) {
			bestDist = d
			best = i
		}
	}
	return best
}

func rgbTo256(r, g, b int) int {
	qr, qg, qb := cubeQ(r), cubeQ(g), cubeQ(b)
	switch {
	case qr == 0 && qg == 0 && qb == 0:
		return 0
	case qr == 5 && qg == 0 && qb == 0:
		return 9
	case qr == 0 && qg == 5 && qb == 0:
		return 10
	case qr == 5 && qg == 5 && qb == 0:
		return 11
	case qr == 0 && qg == 0 && qb == 5:
