			cr, cg, cb := fl.cellColor(er, eg, eb, gray)
			row[bx] = cell{char: ch, r: cr, g: cg, b: cb}
		}
		grid.cells[by] = row
	}
	return grid, false
}

func srgbToLinear(s float64) float64 {
	if s <= 0.04045 {
		return s / 12.92
	}
	return math.Pow((s+0.055)/1.055, 2.4)
}

// ditherImage applies Floyd-Steinberg dithering in linear RGB space,
// returning a black/white RGBA image.
func ditherImage(src *image.RGBA) *image.RGBA {
	w := src.Bounds().Dx()
	h := src.Bounds().Dy()
	// linear values [h][w][3]
	vals := make([][][3]float64, h)
	for y := 0; y < h; y++ {
		row := make([][3]float64, w)
		for x := 0; x < w; x++ {
			r, g, b := pixelRGB(src, x, y)
			row[x] = [3]float64{srgbToLinear(float64(r) / 255), srgbToLinear(float64(g) / 255), srgbToLinear(float64(b) / 255)}
		}
		vals[y] = row
	}
	out := image.NewRGBA(image.Rect(0, 0, w, h))
	type nbor struct {
		dx, dy int
		weight float64
	}
	neigh := []nbor{{1, 0, 7.0 / 16}, {-1, 1, 3.0 / 16}, {0, 1, 5.0 / 16}, {1, 1, 1.0 / 16}}
	for y := 0; y < h; y++ {
		for x := 0; x < w; x++ {
			old := vals[y][x]
			var distBlack, distWhite float64
			for i := 0; i < 3; i++ {
				distBlack += old[i] * old[i]
				d := 1 - old[i]
				distWhite += d * d
			}
			newVal := 0.0
			if distWhite < distBlack {
				newVal = 1
			}
			off := out.PixOffset(x, y)
			v := uint8(0)
			if newVal == 1 {
				v = 255
			}
			out.Pix[off], out.Pix[off+1], out.Pix[off+2], out.Pix[off+3] = v, v, v, 255
			var err [3]float64
			for i := 0; i < 3; i++ {
				err[i] = old[i] - newVal
			}
			for _, nb := range neigh {
				nx, ny := x+nb.dx, y+nb.dy
				if nx < 0 || nx >= w || ny < 0 || ny >= h {
					continue
				}
				for i := 0; i < 3; i++ {
					nv := vals[ny][nx][i] + err[i]*nb.weight
					if nv < 0 {
						nv = 0
					}
					if nv > 1 {
						nv = 1
					}
					vals[ny][nx][i] = nv
				}
			}
		}
	}
	return out
}
