	cmapFmt4 int // offset of format4 subtable or -1
	cmapFmt12 int
}

func parseTTF(data []byte) (*ttfFont, error) {
	if len(data) < 12 {
		return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
	}
	magic := binary.BigEndian.Uint32(data[0:4])
	if magic == 0x74746366 { // 'ttcf'
		if len(data) < 12 {
			return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
		}
		ver := binary.BigEndian.Uint32(data[4:8])
		if ver != 0x00010000 && ver != 0x00020000 {
			return nil, errors.New("freetype: invalid TrueType format: bad TTC version")
		}
		numFonts := binary.BigEndian.Uint32(data[8:12])
		if numFonts == 0 {
			return nil, errors.New("freetype: invalid TrueType format: bad number of TTC fonts")
		}
		if len(data) < 16 {
			return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
		}
		off := int(binary.BigEndian.Uint32(data[12:16]))
		if off+12 > len(data) {
			return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
		}
		return parseTTFFontAt(data, off)
	}
	if magic != 0x00010000 {
		return nil, errors.New("freetype: invalid TrueType format: bad TTF version")
	}
	return parseTTFFontAt(data, 0)
}

func parseTTFFontAt(data []byte, base int) (*ttfFont, error) {
	f := &ttfFont{data: data, tables: map[string][2]uint32{}, cmapFmt4: -1, cmapFmt12: -1}
	if base+12 > len(data) {
		return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
	}
	// "head" Gibberish check mirroring the reference parser's first check.
	numTables := int(binary.BigEndian.Uint16(data[base+4 : base+6]))
	for i := 0; i < numTables; i++ {
		rec := base + 12 + i*16
		if rec+16 > len(data) {
			return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
		}
		tag := string(data[rec : rec+4])
		off := binary.BigEndian.Uint32(data[rec+8 : rec+12])
		length := binary.BigEndian.Uint32(data[rec+12 : rec+16])
		f.tables[tag] = [2]uint32{off, length}
	}
	head, ok := f.tables["head"]
	if !ok {
		return nil, fmt.Errorf("freetype: invalid TrueType format: bad head length: 0")
	}
	if head[1] < 54 {
		// The reference reports the head table length when it is unusable.
		// Many valid fonts have head length 54.
		if head[1] == 0 {
			return nil, fmt.Errorf("freetype: invalid TrueType format: bad head length: 0")
		}
	}
	hoff := int(head[0])
	if hoff+54 > len(data) {
		return nil, errors.New("freetype: invalid TrueType format: TTF data is too short")
	}
	f.upem = int(binary.BigEndian.Uint16(data[hoff+18 : hoff+20]))
	if f.upem == 0 {
		f.upem = 2048
	}
	f.locaLong = int16(binary.BigEndian.Uint16(data[hoff+50:hoff+52])) == 1
	if maxp, ok := f.tables["maxp"]; ok && int(maxp[0])+6 <= len(data) {
		f.numGlyph = int(binary.BigEndian.Uint16(data[int(maxp[0])+4 : int(maxp[0])+6]))
	}
	// locate cmap subtables
	if cmap, ok := f.tables["cmap"]; ok {
		coff := int(cmap[0])
		if coff+4 <= len(data) {
			nt := int(binary.BigEndian.Uint16(data[coff+2 : coff+4]))
			for i := 0; i < nt; i++ {
				rec := coff + 4 + i*8
				if rec+8 > len(data) {
					break
				}
				sub := int(binary.BigEndian.Uint32(data[rec+4 : rec+8]))
				if coff+sub+2 > len(data) {
					continue
				}
				format := binary.BigEndian.Uint16(data[coff+sub : coff+sub+2])
				if format == 4 && f.cmapFmt4 < 0 {
					f.cmapFmt4 = coff + sub
				}
				if format == 12 && f.cmapFmt12 < 0 {
					f.cmapFmt12 = coff + sub
				}
			}
		}
	}
	return f, nil
}

func (f *ttfFont) glyphIndex(r rune) int {
	data := f.data
	if f.cmapFmt12 >= 0 {
		o := f.cmapFmt12
		if o+16 <= len(data) {
			n := int(binary.BigEndian.Uint32(data[o+12 : o+16]))
			lo, hi := 0, n-1
			for lo <= hi {
				mid := (lo + hi) / 2
				rec := o + 16 + mid*12
				if rec+12 > len(data) {
					break
				}
				start := rune(binary.BigEndian.Uint32(data[rec : rec+4]))
				end := rune(binary.BigEndian.Uint32(data[rec+4 : rec+8]))
				base := binary.BigEndian.Uint32(data[rec+8 : rec+12])
				if r < start {
					hi = mid - 1
				} else if r > end {
					lo = mid + 1
				} else {
					return int(base) + int(r-start)
				}
			}
		}
	}
	if f.cmapFmt4 >= 0 {
		o := f.cmapFmt4
		if o+14 <= len(data) {
			segCount := int(binary.BigEndian.Uint16(data[o+6:o+8])) / 2
			endOff := o + 14
			startOff := endOff + segCount*2 + 2
			deltaOff := startOff + segCount*2
			rangeOff := deltaOff + segCount*2
			cp := uint16(r)
			if r > 0xFFFF {
				return 0
			}
			for i := 0; i < segCount; i++ {
				end := binary.BigEndian.Uint16(data[endOff+i*2 : endOff+i*2+2])
				if cp > end {
					continue
				}
				start := binary.BigEndian.Uint16(data[startOff+i*2 : startOff+i*2+2])
				if cp < start {
					return 0
				}
				delta := int16(binary.BigEndian.Uint16(data[deltaOff+i*2 : deltaOff+i*2+2]))
				ro := binary.BigEndian.Uint16(data[rangeOff+i*2 : rangeOff+i*2+2])
				if ro == 0 {
					return (int(cp) + int(delta)) & 0xFFFF
				}
				addr := rangeOff + i*2 + int(ro) + 2*(int(cp)-int(start))
				if addr+2 > len(data) {
					return 0
				}
				gid := binary.BigEndian.Uint16(data[addr : addr+2])
				if gid != 0 {
					gid = uint16((int(gid) + int(delta)) & 0xFFFF)
				}
				return int(gid)
			}
		}
	}
	return 0
}

func (f *ttfFont) glyphOffset(gid int) (int, int, bool) {
	locaTab, ok := f.tables["loca"]
	if !ok {
		return 0, 0, false
	}
	loff := int(locaTab[0])
	var start, end int
	if f.locaLong {
		if loff+gid*4+8 > len(f.data) {
			return 0, 0, false
		}
		start = int(binary.BigEndian.Uint32(f.data[loff+gid*4 : loff+gid*4+4]))
		end = int(binary.BigEndian.Uint32(f.data[loff+gid*4+4 : loff+gid*4+8]))
	} else {
		if loff+gid*2+4 > len(f.data) {
			return 0, 0, false
		}
		start = int(binary.BigEndian.Uint16(f.data[loff+gid*2:loff+gid*2+2])) * 2
		end = int(binary.BigEndian.Uint16(f.data[loff+gid*2+2:loff+gid*2+4])) * 2
	}
	glyfTab, ok := f.tables["glyf"]
	if !ok {
		return 0, 0, false
	}
	goff := int(glyfTab[0])
	return goff + start, goff + end, true
}

type pt2 struct{ x, y float64 }

// glyphOutlines returns a list of contours (each a closed point list, quadratics flattened).
func (f *ttfFont) glyphOutlines(r rune, depth int) [][]pt2 {
	gid := f.glyphIndex(r)
	return f.glyphOutlinesByID(gid, depth)
}

func (f *ttfFont) glyphOutlinesByID(gid int, depth int) [][]pt2 {
	if gid <= 0 || depth > 4 {
		return nil
	}
	start, end, ok := f.glyphOffset(gid)
	if !ok || end <= start || start+10 > len(f.data) {
		return nil
	}
	data := f.data
	nContours := int(int16(binary.BigEndian.Uint16(data[start : start+2])))
	if nContours < 0 {
		// composite glyph
		var out [][]pt2
		pos := start + 10
		for {
			if pos+4 > end {
				break
			}
			flags := binary.BigEndian.Uint16(data[pos : pos+2])
			compGID := int(binary.BigEndian.Uint16(data[pos+2 : pos+4]))
			pos += 4
			var dx, dy float64
			if flags&0x0001 != 0 { // args are words
				if pos+4 > end {
					break
				}
				dx = float64(int16(binary.BigEndian.Uint16(data[pos : pos+2])))
				dy = float64(int16(binary.BigEndian.Uint16(data[pos+2 : pos+4])))
				pos += 4
			} else {
				if pos+2 > end {
					break
				}
				dx = float64(int8(data[pos]))
				dy = float64(int8(data[pos+1]))
				pos += 2
			}
			sx, sy := 1.0, 1.0
			if flags&0x0008 != 0 {
				if pos+2 > end {
					break
				}
				s := float64(int16(binary.BigEndian.Uint16(data[pos:pos+2]))) / 16384.0
				sx, sy = s, s
				pos += 2
			} else if flags&0x0040 != 0 {
				if pos+4 > end {
					break
				}
				sx = float64(int16(binary.BigEndian.Uint16(data[pos:pos+2]))) / 16384.0
				sy = float64(int16(binary.BigEndian.Uint16(data[pos+2:pos+4]))) / 16384.0
				pos += 4
			} else if flags&0x0080 != 0 {
				// 2x2 matrix; ignore off-diagonal, apply diagonal approx
				if pos+8 > end {
					break
				}
				sx = float64(int16(binary.BigEndian.Uint16(data[pos:pos+2]))) / 16384.0
				sy = float64(int16(binary.BigEndian.Uint16(data[pos+6:pos+8]))) / 16384.0
				pos += 8
			}
			sub := f.glyphOutlinesByID(compGID, depth+1)
			for _, contour := range sub {
				var tc []pt2
				for _, p := range contour {
					tc = append(tc, pt2{p.x*sx + dx, p.y*sy + dy})
				}
				out = append(out, tc)
			}
			if flags&0x0020 == 0 { // no more components
				break
			}
		}
		return out
	}
	endPtsOff := start + 10
	if endPtsOff+2*nContours > end {
		return nil
	}
	var endPts []int
	for i := 0; i < nContours; i++ {
		endPts = append(endPts, int(binary.BigEndian.Uint16(data[endPtsOff+i*2:endPtsOff+i*2+2])))
	}
	pos := endPtsOff + 2*nContours
	if pos+2 > end {
		return nil
	}
	instrLen := int(binary.BigEndian.Uint16(data[pos : pos+2]))
	pos += 2 + instrLen
	totalPts := 0
	if len(endPts) > 0 {
		totalPts = endPts[len(endPts)-1] + 1
	}
	var flags []byte
	for len(flags) < totalPts {
		if pos >= end {
			return nil
		}
		fl := data[pos]
		pos++
		flags = append(flags, fl)
		if fl&0x08 != 0 { // repeat
			if pos >= end {
				return nil
			}
			rep := int(data[pos])
			pos++
			for j := 0; j < rep; j++ {
				flags = append(flags, fl)
			}
		}
	}
	flags = flags[:totalPts]
	xs := make([]int, totalPts)
	cur := 0
	for i := 0; i < totalPts; i++ {
		fl := flags[i]
		if fl&0x02 != 0 { // x-short
			if pos >= end {
				return nil
			}
			v := int(data[pos])
			pos++
			if fl&0x10 != 0 {
				cur += v
			} else {
				cur -= v
			}
		} else {
			if fl&0x10 == 0 {
				if pos+1 >= end {
					return nil
				}
				cur += int(int16(binary.BigEndian.Uint16(data[pos : pos+2])))
				pos += 2
			}
		}
		xs[i] = cur
	}
	ys := make([]int, totalPts)
	cur = 0
	for i := 0; i < totalPts; i++ {
		fl := flags[i]
		if fl&0x04 != 0 { // y-short
			if pos >= end {
				return nil
			}
			v := int(data[pos])
			pos++
			if fl&0x20 != 0 {
				cur += v
			} else {
				cur -= v
			}
		} else {
			if fl&0x20 == 0 {
				if pos+1 >= end {
					return nil
				}
				cur += int(int16(binary.BigEndian.Uint16(data[pos : pos+2])))
				pos += 2
			}
		}
		ys[i] = cur
	}
	// Build contours with on/off curve handling
	var contours [][]pt2
	prevEnd := -1
	for ci := 0; ci < nContours; ci++ {
		endIdx := endPts[ci]
		type gpt struct {
			p      pt2
			on     bool
		}
		var pts []gpt
		for i := prevEnd + 1; i <= endIdx; i++ {
			pts = append(pts, gpt{pt2{float64(xs[i]), float64(ys[i])}, flags[i]&0x01 != 0})
		}
		prevEnd = endIdx
		if len(pts) == 0 {
			continue
		}
		// Normalise start: start with an on-curve point
		if !pts[0].on {
			if pts[len(pts)-1].on {
				// rotate
				pts = append([]gpt{pts[len(pts)-1]}, pts[:len(pts)-1]...)
			} else {
				mid := pt2{(pts[0].p.x + pts[len(pts)-1].p.x) / 2, (pts[0].p.y + pts[len(pts)-1].p.y) / 2}
				pts = append([]gpt{{mid, true}}, pts...)
			}
		}
		var contour []pt2
		contour = append(contour, pts[0].p)
		for i := 1; i <= len(pts); i++ {
			curP := pts[i%len(pts)]
			if curP.on {
				contour = append(contour, curP.p)
			} else {
				next := pts[(i+1)%len(pts)]
				ctrl := curP.p
				endP := next.p
				if !next.on {
					endP = pt2{(ctrl.x + next.p.x) / 2, (ctrl.y + next.p.y) / 2}
					i++ // consumed next as well? avoid complexity: keep simple handling below
					// When two off-curve points in a row, the end is their midpoint;
					// the following iteration will re-process 'next' as a control
					// point, which yields a slightly different curve but is close.
					i--
				}
				// flatten quadratic contour start->ctrl->end
				startP := contour[len(contour)-1]
				const steps = 8
				for s := 1; s <= steps; s++ {
					t := float64(s) / steps
					mt := 1 - t
					x := mt*mt*startP.x + 2*mt*t*ctrl.x + t*t*endP.x
					y := mt*mt*startP.y + 2*mt*t*ctrl.y + t*t*endP.y
					contour = append(contour, pt2{x, y})
				}
				if !next.on {
					// next will be handled as control next iteration
					continue
				}
				i++ // skip the on-curve end we just consumed
				if i > len(pts) {
					break
				}
				_ = i
			}
		}
		contours = append(contours, contour)
	}
	return contours
}

// renderGlyphMask renders r into a 24x38 grayscale tile using the same pen
// position as the built-in bitmap font (pen at x=5, baseline y=26) at the
// given pixel size (pixels per em).
func (f *ttfFont) renderGlyphMask(r rune, size float64) []byte {
	tileW, tileH := 24, 38
	mask := make([]byte, tileW*tileH)
	contours := f.glyphOutlines(r, 0)
	if len(contours) == 0 {
		return mask
	}
	scale := size / float64(f.upem)
	penX, penY := 5.0, 26.0
	// Transform contours to tile pixel coordinates (y down)
	var polys [][]pt2
	for _, c := range contours {
		var poly []pt2
		for _, p := range c {
			poly = append(poly, pt2{penX + p.x*scale, penY - p.y*scale})
		}
		polys = append(polys, poly)
	}
	const SS = 4
	for y := 0; y < tileH; y++ {
		for x := 0; x < tileW; x++ {
			insideCount := 0
			for sy := 0; sy < SS; sy++ {
				for sx := 0; sx < SS; sx++ {
					px := float64(x) + (float64(sx)+0.5)/SS
					py := float64(y) + (float64(sy)+0.5)/SS
					if pointInPolys(px, py, polys) {
						insideCount++
					}
				}
			}
			if insideCount > 0 {
				mask[y*tileW+x] = uint8((insideCount*255 + (SS*SS)/2) / (SS * SS))
			}
		}
	}
	return mask
}

func pointInPolys(x, y float64, polys [][]pt2) bool {
	// non-zero winding
	winding := 0
	for _, poly := range polys {
		n := len(poly)
		for i := 0; i < n; i++ {
			a := poly[i]
			b := poly[(i+1)%n]
			if a.y <= y {
				if b.y > y && isLeft(a, b, x, y) > 0 {
					winding++
				}
			} else {
				if b.y <= y && isLeft(a, b, x, y) < 0 {
					winding--
				}
			}
		}
	}
	return winding != 0
}

func isLeft(a, b pt2, x, y float64) float64 {
	return (b.x-a.x)*(y-a.y) - (x-a.x)*(b.y-a.y)
}

var _ = math.Pi
