func loadFont(path string) (*loadedFont, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("unable to open font file: %v", err)
	}
	ttf, perr := parseTTF(data)
	if perr != nil {
		return nil, fmt.Errorf("unable to parse font file: %v", perr)
	}
	return &loadedFont{ttf: ttf}, nil
