package main

import (
	"fmt"
	"image"
	"image/color"
	"image/color/palette"
	"image/draw"
	"image/gif"
	"image/png"
	"os"
	"strings"
	"sync"
)

func saveBgColor(fl *flags) color.RGBA {
	bg := fl.saveBg
	var r, g, b, a int
	if len(bg) == 4 {
		r, g, b, a = bg[0], bg[1], bg[2], bg[3]
	} else {
		r, g, b, a = 0, 0, 0, 100
	}
	alpha := uint8(float64(255) * float64(a) / 100)
	return color.RGBA{uint8(r), uint8(g), uint8(b), alpha}
}

func normalizeSavePath(p string) string {
	if !strings.HasSuffix(p, "/") {
		p += "/"
	}
	return p
}

func savePathStatCheck(spath string) error {
	if _, err := os.Stat(spath); err != nil {
		if os.IsNotExist(err) {
			return fmt.Errorf("can't save file: %v", err)
		}
	}
	return nil
}

func glyphMask(r rune, isBraille bool, lf *loadedFont) []byte {
	if lf != nil && lf.ttf != nil {
		return lf.ttf.renderGlyphMask(r, 22)
	}
	if isBraille {
		if m, ok := brailleMasks[r]; ok {
			return m
		}
	} else {
		if m, ok := asciiMasks[r]; ok {
			return m
		}
	}
	// Fallback: try a system monospace font once.
	if m := fallbackFontMask(r); m != nil {
		return m
	}
	return make([]byte, 24*38)
}

var fallbackOnce sync.Once
var fallbackTTF *ttfFont

func fallbackFontMask(r rune) []byte {
	fallbackOnce.Do(func() {
		for _, p := range []string{
			"/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf",
			"/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
		} {
			data, err := os.ReadFile(p)
			if err != nil {
				continue
			}
			if ttf, err := parseTTF(data); err == nil {
				fallbackTTF = ttf
				return
			}
		}
	})
	if fallbackTTF == nil {
		return nil
	}
	return fallbackTTF.renderGlyphMask(r, 22)
}

func firstRune(s string) rune {
	for _, r := range s {
		return r
	}
	return 0
}

func blendOver(dst *image.RGBA, x, y int, sr, sg, sb int, mask int) {
	if mask <= 0 {
		return
	}
	if x < 0 || y < 0 || x >= dst.Bounds().Dx() || y >= dst.Bounds().Dy() {
		return
	}
	off := dst.PixOffset(x, y)
	if mask >= 255 {
		dst.Pix[off] = uint8(sr)
		dst.Pix[off+1] = uint8(sg)
		dst.Pix[off+2] = uint8(sb)
		dst.Pix[off+3] = 255
		return
	}
	inv := 255 - mask
	// Source is opaque colour (premultiplied == sr,sg,sb, alpha 255)
	dst.Pix[off] = uint8((sr*mask + int(dst.Pix[off])*inv + 127) / 255)
	dst.Pix[off+1] = uint8((sg*mask + int(dst.Pix[off+1])*inv + 127) / 255)
	dst.Pix[off+2] = uint8((sb*mask + int(dst.Pix[off+2])*inv + 127) / 255)
	dst.Pix[off+3] = uint8((255*mask + int(dst.Pix[off+3])*inv + 127) / 255)
}

func fillBackground(img *image.RGBA, bg color.RGBA) {
	// Convert through RGBAModel as the reference does when filling an
	// RGBA image with a (possibly translucent) colour.
	bgconv := color.RGBAModel.Convert(bg).(color.RGBA)
	for i := 0; i < len(img.Pix); i += 4 {
		img.Pix[i] = bgconv.R
		img.Pix[i+1] = bgconv.G
		img.Pix[i+2] = bgconv.B
		img.Pix[i+3] = bgconv.A
	}
}

// renderGridImage renders an art grid at the fixed PNG cell size (14x28).
func renderGridImage(grid *artGrid, fl *flags, lf *loadedFont) *image.RGBA {
	w := grid.width*14 + 10
	h := grid.height*28 + 10
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	fillBackground(img, saveBgColor(fl))
	for row := 0; row < grid.height; row++ {
		for col := 0; col < grid.width; col++ {
			c := grid.cells[row][col]
			if c.char == "" {
				continue
			}
			mask := glyphMask(firstRune(c.char), fl.braille, lf)
			// premultiplied source values: cell colour is opaque
			for ty := 0; ty < 38; ty++ {
				for tx := 0; tx < 24; tx++ {
					m := int(mask[ty*24+tx])
					if m == 0 {
						continue
					}
					blendOver(img, col*14+tx, row*28+ty, c.r, c.g, c.b, m)
				}
			}
		}
	}
	return img
}

func saveImageFile(grid *artGrid, fl *flags, lf *loadedFont, savePath, imgName string) (string, error) {
	spath := normalizeSavePath(savePath)
	if err := savePathStatCheck(spath); err != nil {
		return "", err
	}
	full := spath + imgName + "-ascii-art.png"
	img := renderGridImage(grid, fl, lf)
	f, err := os.Create(full)
	if err != nil {
		return "", fmt.Errorf("can't save file: %v", err)
	}
	encErr := png.Encode(f, img)
	f.Close()
	if encErr != nil {
		return "", fmt.Errorf("can't save file: %v", encErr)
	}
	return full, nil
}

func saveTxtFile(grid *artGrid, fl *flags, savePath, imgName string) (string, error) {
	spath := normalizeSavePath(savePath)
	if _, err := os.Stat(spath); err != nil {
		if os.IsNotExist(err) {
			return "", fmt.Errorf("can't save file: save path %s does not exist", spath)
		}
	}
	full := spath + imgName + "-ascii-art.txt"
	if err := os.WriteFile(full, []byte(grid.plainString()), 0644); err != nil {
		return "", fmt.Errorf("can't save file: %v", err)
	}
	return full, nil
}

// renderGifFrame renders a frame at the (empirically determined) GIF canvas
// size for the given source-gif frame size, by rendering at PNG cell size
// and resizing to the canvas.
func renderGifFrame(grid *artGrid, fl *flags, lf *loadedFont, gifW, gifH int) *image.RGBA {
	wa, ha := grid.width, grid.height
	var ow, oh int
	if wa* gifH > gifW*ha { // Wa/Ha > Wg/Hg
		ow = int(float64(gifH)*float64(wa)/(2*float64(ha))) + 10
		oh = gifH + 10
	} else {
		ow = gifW + 10
		oh = int(2*float64(gifW)*float64(ha)/float64(wa)) + 10
	}
	// Render at standard size then resize; glyphs are drawn with masks,
	// this closely matches size/colour while font scaling is approximate.
	base := renderGridImage(grid, fl, lf)
	if ow <= 0 || oh <= 0 {
		return base
	}
	resized := resizeImage(base, ow, oh)
	return resized
}

func saveGifFile(grids []*artGrid, fl *flags, lf *loadedFont, savePath, imgName string, delays []int, loopCount int, gifW, gifH int) error {
	spath := normalizeSavePath(savePath)
	if err := savePathStatCheck(spath); err != nil {
		return err
	}
	full := spath + imgName + "-ascii-art.gif"
	fmt.Print("Saving gif... 0%\r")
	var paletted []*image.Paletted
	for i, grid := range grids {
		rendered := renderGifFrame(grid, fl, lf, gifW, gifH)
		pal := image.NewPaletted(rendered.Bounds(), palette.Plan9)
		draw.Draw(pal, pal.Bounds(), rendered, image.Point{}, draw.Src)
		paletted = append(paletted, pal)
		fmt.Printf("Saving gif... %d%%\r", (i+1)*100/len(grids))
	}
	f, err := os.Create(full)
	if err != nil {
		return fmt.Errorf("can't save file: %v", err)
	}
	outGif := &gif.GIF{Image: paletted, Delay: delays, LoopCount: loopCount}
	encErr := gif.EncodeAll(f, outGif)
	f.Close()
	if encErr != nil {
		return fmt.Errorf("can't save file: %v", encErr)
	}
	fmt.Print("                     \r")
	fmt.Println("Saved " + full)
	return nil
}
GO"}

