{"command":"cat > main.go << 'GO'
package main

import (
	"bytes"
	"fmt"
	"image"
	"image/gif"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

func main() {
	fl, args, err := parseArgs(os.Args[1:])
	if err != nil {
		fatalParseError(err)
	}
	if fl.help {
		fmt.Print(helpText)
		return
	}
	if fl.version {
		fmt.Println("v1.13.1")
		return
	}
	run(fl, args)
}

func printGlobalError(msg string) {
	fmt.Print(msg + "\n\n")
}

// per-file "outer" errors: single newline when only-saving, else blank line too
func (fl *flags) printProcessError(msg string) {
	if fl.onlySave {
		fmt.Println(msg)
	} else {
		fmt.Print(msg + "\n\n")
	}
}
func printSaveError(msg string) {
	fmt.Print(msg + "\n\n")
}

func validateFlags(fl *flags) string {
	// Returns the (bare) error message text without the formatting,
	// or "" when valid. Prefix is handled by caller: some messages do
	// not start with "Error:" in the original.
	if len(fl.customMap) == 1 {
		return "Need at least 2 characters for --map flag"
	}
	if len(fl.dimensions) != 0 && len(fl.dimensions) != 2 {
		return fmt.Sprintf("Error: requires 2 dimensions, got %d", len(fl.dimensions))
	}
	if len(fl.dimensions) == 2 && (fl.dimensions[0] <= 0 || fl.dimensions[1] <= 0) {
		return "Error: invalid values for dimensions"
	}
	if fl.width != 0 && fl.height != 0 {
		return "Error: both --width and --height can't be set. Use --dimensions instead"
	}
	if fl.width < 0 {
		return "Error: invalid value for width"
	}
	if fl.height < 0 {
		return "Error: invalid value for height"
	}
	if len(fl.saveBg) != 0 && len(fl.saveBg) != 4 {
		return fmt.Sprintf("Error: --save-bg requires 4 values for RGBA, got %d", len(fl.saveBg))
	}
	if len(fl.saveBg) == 4 {
		rgbBad := false
		for i := 0; i < 3; i++ {
			if fl.saveBg[i] < 0 || fl.saveBg[i] > 255 {
				rgbBad = true
			}
		}
		opacityBad := fl.saveBg[3] < 0 || fl.saveBg[3] > 100
		if rgbBad || opacityBad {
			return "Error: RBG values must be between 0 and 255\nError: Opacity value must be between 0 and 100"
		}
	}
	if len(fl.fontColor) != 0 && len(fl.fontColor) != 3 {
		return fmt.Sprintf("Error: --font-color requires 3 values for RGB, got %d", len(fl.fontColor))
	}
	if len(fl.fontColor) == 3 {
		for i := 0; i < 3; i++ {
			if fl.fontColor[i] < 0 || fl.fontColor[i] > 255 {
				return "Error: RBG values must be between 0 and 255"
			}
		}
	}
	if fl.threshold < 0 || fl.threshold > 255 {
		return "Error: threshold must be between 0 and 255"
	}
	if fl.dither && !fl.braille {
		return "Error: image dithering is only reserved for --braille flag"
	}
	if fl.onlySave && fl.saveImg == "" && fl.saveTxt == "" && fl.saveGif == "" {
		return "Error: you need to supply one of --save-img, --save-txt or --save-gif for using --only-save"
	}
	return ""
}

func run(fl *flags, args []string) {
	// GIF multiplicity checks (skipped when only-saving)
	if !fl.onlySave {
		gifCount := 0
		for _, a := range args {
			if strings.HasSuffix(a, ".gif") {
				gifCount++
			}
		}
		if gifCount > 0 && len(args) > gifCount {
			printGlobalError("Error: There are other inputs along with GIFs\nDue to the potential looping nature of GIFs, non-GIFs must not be supplied alongside")
			return
		}
		if gifCount > 1 {
			printGlobalError("Error: There are multiple GIFs supplied\nDue to the potential looping nature of GIFs, only one GIF per command is supported")
			return
		}
	}
	if fl.formats {
		fmt.Print(formatsText)
		return
	}
	if len(args) == 0 {
		printGlobalError("Error: Need at least 1 input path/url or piped input\nUse the -h flag for more info")
		return
	}
	// piped input alongside others
	hasPiped := false
	for _, a := range args {
		if a == "-" {
			hasPiped = true
		}
	}
	if hasPiped && len(args) > 1 {
		printGlobalError("Error: You cannot pass in piped input alongside other inputs")
		return
	}
	if msg := validateFlags(fl); msg != "" {
		printGlobalError(msg)
		return
	}
	for _, path := range args {
		processInput(fl, path)
	}
}

func isURLArg(s string) bool {
	return len(s) > 7 && (strings.HasPrefix(s, "http://") || strings.HasPrefix(s, "https://"))
}

func imageNameForSave(path string, isPiped bool) string {
	if isPiped {
		return "piped-img"
	}
	base := filepath.Base(path)
	ext := filepath.Ext(base)
	return strings.TrimSuffix(base, ext)
}

// processInput handles one positional argument end-to-end.
func processInput(fl *flags, path string) {
	isPiped := path == "-"
	isURL := false
	var data []byte
	var gifReaderData []byte // for gif suffix paths we decode from the acquired bytes
	var font *loadedFont

	if isPiped {
		if fl.font != "" {
			lf, err := loadFont(fl.font)
			if err != nil {
				fl.printProcessError(err.Error())
				return
			}
			font = lf
		}
		b, _ := io.ReadAll(os.Stdin)
		data = b
		gifReaderData = b
	} else if isURLArg(path) {
		isURL = true
		fmt.Print("Fetching file from url...\r")
		resp, err := http.Get(path)
		if err != nil {
			fl.printProcessError(fmt.Sprintf("Error: can't fetch content: %v", err))
			return
		}
