			fl.printProcessError(fmt.Sprintf("Error: can't fetch content: %v", err))
			return
		}
		defer resp.Body.Close()
		fmt.Print("                          \r")
		if fl.font != "" {
			lf, err := loadFont(fl.font)
			if err != nil {
				fl.printProcessError(err.Error())
				return
			}
			font = lf
		}
		b, _ := io.ReadAll(resp.Body)
		data = b
		gifReaderData = b
	} else {
		f, err := os.Open(path)
		if err != nil {
			fl.printProcessError(fmt.Sprintf("Error: unable to open file: %v", err))
			return
		}
		if fl.font != "" {
			lf, err := loadFont(fl.font)
			if err != nil {
				f.Close()
				fl.printProcessError(err.Error())
				return
			}
			font = lf
		}
		b, _ := io.ReadAll(f)
		f.Close()
		data = b
		gifReaderData = b
	}
	_ = isURL

	isGif := false
	if isPiped {
		// detect by format magic
		if len(data) >= 6 && (string(data[:6]) == "GIF87a" || string(data[:6]) == "GIF89a") {
			isGif = true
		}
	} else if strings.HasSuffix(path, ".gif") {
		isGif = true
	}

	imgName := imageNameForSave(path, isPiped)

	if isGif {
		processGif(fl, path, gifReaderData, font, imgName, isPiped, isURL)
		return
	}

	// Still image path
	img, _, err := decodeImageBytes(data)
	if err != nil {
		label := path
		if isPiped {
			label = "piped input"
			fl.printProcessError(fmt.Sprintf("Error: can't decode %s: %v", label, err))
		} else {
			fl.printProcessError(fmt.Sprintf("Error: can't decode %s: %v", label, err))
		}
		return
	}
	grid, colourErr := convertToArt(img, fl)
	if colourErr {
		fl.printProcessError("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
		return
	}
	// Saves for still images
	if fl.saveImg != "" {
		saved, err := saveImageFile(grid, fl, font, fl.saveImg, imgName)
		if err != nil {
			printSaveError("Error: " + err.Error())
			return
		}
		if fl.onlySave {
			fmt.Println("Saved " + saved)
		}
	}
	if fl.saveTxt != "" {
		saved, err := saveTxtFile(grid, fl, fl.saveTxt, imgName)
		if err != nil {
			printSaveError("Error: " + err.Error())
			return
		}
		if fl.onlySave {
			fmt.Println("Saved " + saved)
		}
	}
	// --save-gif is ignored for still images
	if !fl.onlySave {
		if colorRequested(fl) {
			fmt.Println(grid.coloredString(terminalColorType(), fl.colorBg))
		} else {
			fmt.Println(grid.plainString())
		}
	}
}

func processGif(fl *flags, path string, data []byte, font *loadedFont, imgName string, isPiped, isURL bool) {
	g, err := gif.DecodeAll(bytes.NewReader(data))
	if err != nil {
		label := path
		if isPiped {
			label = "piped input"
		}
		fl.printProcessError(fmt.Sprintf("Error: can't decode %s: %v", label, err))
		return
	}
	if len(g.Image) == 0 {
		label := path
		if isPiped {
			label = "piped input"
		}
		fl.printProcessError(fmt.Sprintf("Error: can't decode %s: image: unknown format", label))
		return
	}
	fmt.Print("Generating ascii art... 0%\r")
	// subimage check against the first frame's size
	defW := g.Image[0].Bounds().Dx()
	defH := g.Image[0].Bounds().Dy()
	for _, fr := range g.Image {
		if fr.Bounds().Dx() < defW || fr.Bounds().Dy() < defH {
			display := path
			if isURL {
				display = filepath.Base(path)
			}
			msg := fmt.Sprintf("%s contains subimages smaller than default width and height\n\nProcess aborted because ascii-image-converter doesn't support subimage placement and transparency in GIFs\n", display)
			// This error is printed with a single Println by the gif path
			fmt.Println("Error: " + msg)
			return
		}
	}
	var grids []*artGrid
	for i, fr := range g.Image {
		// colour-support errors occur during frame conversion
		grid, colourErr := convertToArt(fr, fl)
		if colourErr {
			fmt.Println("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
			return
		}
		grids = append(grids, grid)
		fmt.Printf("Generating ascii art... %d%%\r", (i+1)*100/len(g.Image))
	}
	fmt.Print("                              \r")
	// Save gif if requested
	if fl.saveGif != "" {
		if err := saveGifFile(grids, fl, font, fl.saveGif, imgName, g.Delay, g.LoopCount, defW, defH); err != nil {
			printSaveError("Error: " + err.Error())
			return
		}
	}
	if fl.onlySave {
		return
	}
	// Playback
	plays := 0
	for {
		for i, grid := range grids {
			if colorRequested(fl) {
				fmt.Println(grid.coloredString(terminalColorType(), fl.colorBg))
			} else {
				fmt.Println(grid.plainString())
			}
			delay := 0
			if i < len(g.Delay) {
				delay = g.Delay[i]
			}
			if delay > 0 {
				time.Sleep(time.Duration(delay) * 10 * time.Millisecond)
			}
		}
		plays++
		if g.LoopCount > 0 && plays >= g.LoopCount {
			break
		}
	}
	fmt.Println()
}

