package main
import ("fmt";"math")
func sinc(x float64) float64 { if x==0 {return 1}; x*=math.Pi; return math.Sin(x)/x }
func lz(x float64) float64 { if x==0 {return 1}; if x<=-3||x>=3 {return 0}; return sinc(x)*sinc(x/3)}
func calc(L int, reverse bool, pair bool) float64 {
 scale:=float64(L); center:=0.5*scale-0.5; var sum,total float64
 order:=make([]int,L); for i:=range order {order[i]=i}; if reverse { for i,j:=0,L-1;i<j;i,j=i+1,j-1 {order[i],order[j]=order[j],order[i]} }
 if pair {
   // sum pairs symmetrically
   for i:=0;i<L/2;i++ { for _,j:=range []int{i,L-1-i} { w:=lz((center-float64(j))/scale); sum+=w; v:=float64(j*17); if L==256 {v=float64(j)}; total+=v*w } }
 } else {
  for _,j:=range order { w:=lz((center-float64(j))/scale); sum+=w; v:=float64(j*17); if L==256 {v=float64(j)}; total+=v*w }
 }
 return total/sum
}
func main(){
 for _,L:=range []int{16,256}{ fmt.Println(L, calc(L,false,false), calc(L,true,false), calc(L,false,true)) }
}
