     switch mode {
     case "fwd": for _,c:=range cs {total+=float64(c.j)*c.w; wsum2+=c.w}; return total/wsum2
     case "rev": for k:=len(cs)-1;k>=0;k-- {c:=cs[k]; total+=float64(c.j)*c.w; wsum2+=c.w}; return total/wsum2
     case "normF": for _,c:=range cs {total+=float64(c.j)*(c.w/wsum)}; return total
     case "normR": for k:=len(cs)-1;k>=0;k-- {c:=cs[k]; total+=float64(c.j)*(c.w/wsum)}; return total
