 total=f32(0); s=f32(0)
 for j,w in cs:
   total=f32(total+f32(f32(j)*f32(w))); s=f32(s+f32(w))
 print("  f32acc", total/s if s else None, total, s)
 # coeff quantized to ... int weights * 1000 etc
 for denom in [256,1024,4096,65536]:
   ints=[round(w*denom) for j,w in cs]
   total=sum(j*iw for (j,w),iw in zip(cs,ints)); s=sum(ints); print(" intden",denom,total/s)
