package main

import (
	"image"
	"image/draw"
)

// resizeNRGBA performs the alpha-aware resize used for *image.NRGBA
// inputs: colours are premultiplied, resized, then un-premultiplied back
// to NRGBA after each pass. The returned image is a display RGBA whose
// pixel values are the premultiplied values obtained via the standard
// RGBA() conversion of the final NRGBA.
func resizeNRGBA(src *image.NRGBA, dstW, dstH int) *image.RGBA {
	if dstW <= 0 || dstH <= 0 {
		return image.NewRGBA(image.Rectangle{})
	}
	inter := nrgbaPassHorizontal(src, dstW)
	final := nrgbaPassVertical(inter, dstH)
	out := image.NewRGBA(image.Rect(0, 0, dstW, dstH))
	draw.Draw(out, out.Bounds(), final, final.Bounds().Min, draw.Src)
	return out
}

func nrgbaPremul(c uint8, a uint8) float64 {
	r16 := (uint32(c) * 0x101 * uint32(a)) / 0xff
	return float64(r16) / 257.0
}

func nrgbaPassHorizontal(src *image.NRGBA, dstW int) *image.NRGBA {
	srcW := src.Bounds().Dx()
	srcH := src.Bounds().Dy()
	coeffs := resizeCoeffs(srcW, dstW)
	dst := image.NewNRGBA(image.Rect(0, 0, dstW, srcH))
	for y := 0; y < srcH; y++ {
		for x := 0; x < dstW; x++ {
			var pr, pg, pb, pa, wsum float64
			for ci := len(coeffs[x]) - 1; ci >= 0; ci-- {
				c := coeffs[x][ci]
				off := y*src.Stride + c.idx*4
				r, g, b, a := src.Pix[off], src.Pix[off+1], src.Pix[off+2], src.Pix[off+3]
				w := c.weight
				wsum += w
				pr += nrgbaPremul(r, a) * w
				pg += nrgbaPremul(g, a) * w
				pb += nrgbaPremul(b, a) * w
				pa += float64(a) * w
			}
			if wsum != 0 {
				pr /= wsum
				pg /= wsum
				pb /= wsum
				pa /= wsum
			}
			doff := y*dst.Stride + x*4
			dst.Pix[doff+3] = clampRound(pa)
			if pa > 0 {
				dst.Pix[doff+0] = clampRound(pr * 255 / pa)
				dst.Pix[doff+1] = clampRound(pg * 255 / pa)
				dst.Pix[doff+2] = clampRound(pb * 255 / pa)
			}
		}
	}
	return dst
