cat > fontdata.go << 'GO'
package main

import (
	"bytes"
	"compress/zlib"
	_ "embed"
	"io"
)

//go:embed ascii_masks.dat
var asciiMasksCompressed []byte

//go:embed braille_masks.dat
var brailleMasksCompressed []byte

// Captured bitmap glyph masks for the built-in fonts.
// Each mask is a 24x38 grayscale tile (row-major), pen at (5,26).
var asciiMasks = map[rune][]byte{}
var brailleMasks = map[rune][]byte{}

func init() {
	if raw, err := decompressZlib(asciiMasksCompressed); err == nil {
		for i := 0; i+1 <= 95; i++ {
			start := i * 24 * 38
			if start+24*38 <= len(raw) {
				asciiMasks[rune(32+i)] = raw[start : start+24*38]
			}
		}
	}
	if raw, err := decompressZlib(brailleMasksCompressed); err == nil {
		for i := 0; i < 256; i++ {
			start := i * 24 * 38
			if start+24*38 <= len(raw) {
				brailleMasks[rune(0x2800+i)] = raw[start : start+24*38]
			}
		}
	}
}

func decompressZlib(b []byte) ([]byte, error) {
	r, err := zlib.NewReader(bytes.NewReader(b))
	if err != nil {
		return nil, err
	}
	defer r.Close()
	return io.ReadAll(r)
}
GO
