import "C"

import (
	"errors"
	"image"
	"sync"
	"unsafe"
)

var webpOnce sync.Once
var webpDecodePtr unsafe.Pointer
var webpFreePtr unsafe.Pointer
var webpHandlePtr unsafe.Pointer

func initWebP() {
	h := C.webp_handle()
	if h == nil {
		return
	}
	webpHandlePtr = h
	webpDecodePtr = C.dlsym(h, C.CString("WebPDecodeRGBA"))
	webpFreePtr = C.dlsym(h, C.CString("WebPFree"))
}

func decodeWEBP(data []byte) (image.Image, error) {
	// Verify chunk type, mirroring format sniffing: only VP8/VP8L/VP8X
	// are recognised as WebP; other RIFF/WEBP data is an unknown format.
	if len(data) < 16 {
		return nil, image.ErrFormat
	}
	chunk := string(data[12:16])
	if chunk != "VP8 " && chunk != "VP8L" && chunk != "VP8X" {
		return nil, image.ErrFormat
