import pathlib
p=pathlib.Path("main.go")
t=p.read_text()
start=t.index("func processInput(fl *flags, path string) {")
end=t.index("func processGif(")
replacement = r'''func processInput(fl *flags, path string) {
	isPiped := path == "-"
	isURL := false
	var data []byte
	var font *loadedFont

	imgName := imageNameForSave(path, isPiped)

	if isPiped {
		if fl.font != "" {
			lf, err := loadFont(fl.font)
			if err != nil {
				fl.printProcessError(err.Error())
				return
			}
			font = lf
		}
		b, _ := io.ReadAll(os.Stdin)
		data = b
		isGif := len(data) >= 6 && (string(data[:6]) == "GIF87a" || string(data[:6]) == "GIF89a")
		if isGif {
			processGif(fl, path, bytes.NewReader(data), font, imgName, true, false)
			return
		}
		processStillData(fl, path, data, font, imgName, true)
		return
	}

	if isURLArg(path) {
		isURL = true
		fmt.Print("Fetching file from url...\r")
		resp, err := http.Get(path)
		if err != nil {
			fl.printProcessError(fmt.Sprintf("Error: can't fetch content: %v", err))
			return
		}
		defer resp.Body.Close()
		fmt.Print("                          \r")
		if fl.font != "" {
			lf, err := loadFont(fl.font)
			if err != nil {
				fl.printProcessError(err.Error())
				return
			}
			font = lf
		}
		if strings.HasSuffix(path, ".gif") {
			processGif(fl, path, resp.Body, font, imgName, false, isURL)
			return
		}
		b, _ := io.ReadAll(resp.Body)
		data = b
		processStillData(fl, path, data, font, imgName, false)
		return
	}

	f, err := os.Open(path)
	if err != nil {
		fl.printProcessError(fmt.Sprintf("Error: unable to open file: %v", err))
		return
	}
	defer f.Close()
	if fl.font != "" {
		lf, err := loadFont(fl.font)
		if err != nil {
			fl.printProcessError(err.Error())
			return
		}
		font = lf
	}
	if strings.HasSuffix(path, ".gif") {
		processGif(fl, path, f, font, imgName, false, false)
		return
	}
	b, _ := io.ReadAll(f)
	data = b
	processStillData(fl, path, data, font, imgName, false)
}

func processStillData(fl *flags, path string, data []byte, font *loadedFont, imgName string, isPiped bool) {
	img, _, err := decodeImageBytes(data)
	if err != nil {
		label := path
		if isPiped {
			label = "piped input"
		}
		fl.printProcessError(fmt.Sprintf("Error: can't decode %s: %v", label, err))
		return
	}
	grid, colourErr := convertToArt(img, fl)
	if colourErr {
		fl.printProcessError("Error: your terminal supports neither 24-bit nor 8-bit colors. Other coloring options aren't available")
		return
	}
	// Saves for still images
	if fl.saveImg != "" {
		saved, err := saveImageFile(grid, fl, font, fl.saveImg, imgName)
		if err != nil {
			printSaveError("Error: " + err.Error())
			return
		}
		if fl.onlySave {
			fmt.Println("Saved " + saved)
		}
	}
	if fl.saveTxt != "" {
		saved, err := saveTxtFile(grid, fl, fl.saveTxt, imgName)
		if err != nil {
			printSaveError("Error: " + err.Error())
			return
		}
		if fl.onlySave {
			fmt.Println("Saved " + saved)
		}
	}
	// --save-gif is ignored for still images
	if !fl.onlySave {
		if colorRequested(fl) {
			fmt.Println(grid.coloredString(terminalColorType(), fl.colorBg))
		} else {
			fmt.Println(grid.plainString())
		}
	}
}

'''
t=t[:start]+replacement+t[end:]
# adjust processGif signature to accept io.Reader
t=t.replace("func processGif(fl *flags, path string, data []byte, font *loadedFont, imgName string, isPiped, isURL bool) {\n\tg, err := gif.DecodeAll(bytes.NewReader(data))", "func processGif(fl *flags, path string, reader io.Reader, font *loadedFont, imgName string, isPiped, isURL bool) {\n\tg, err := gif.DecodeAll(reader)")
p.write_text(t)
